\label{MaAs}
We assume that the shear flow $(b(y),0)$, $y\in \mathbb{T}$ satisfies the following conditions:
\begin{itemize}
\item $b\in C^6(\mathbb{T})$. The set $S:=\{y\in\mathbb{T}: b'(y)=0\}=\{y_{1\ast}, y_{2\ast}\}$, and for some $\varkappa \in(0,1)$, we have
\begin{equation}\label{asp1}
|b''(y)|\in[\varkappa,1/\varkappa]\,\,{\rm for\,\,}y\in S, \quad{\rm and}\quad\|b\|_{C^6(\mathbb{T})}\leq1/\varkappa.
\end{equation}

\item The linearized operator $L_k: L^2(\mathbb{T})\to L^2(\mathbb{T})$ with $ \kappa k\in\mathbb{Z}\backslash\{0\}$ defined for $g\in L^2(\mathbb{T})$ as
\begin{equation}\label{asp2}
L_kg(y):=b(y)g(y)-b''(y)h(y), \quad{\rm where}\,\,(-k^2+\partial_y^2)h(y)=g(y),\,\,y\in\mathbb{T},
\end{equation}
has no eigenvalues in $\mathbb{C}$, nor generalized embedded eigenvalues (also called singular limiting modes) in $\{b(y), y\in\mathbb{T}\}$ (see Definition \ref{emb1}).
\end{itemize}

\label{thm1}
Assume that $\omega\in C([0,\infty), H^{4}(\mathbb{T}_{2\pi \kappa} \times \mathbb{T} ))$ with the associated stream function $ \psi(t,\cdot)$ is the unique solution to \eqref{Main1}, with initial data $\omega_0\in H^4(\mathbb{T}_{2\pi \kappa}\times\mathbb{T})$ satisfying for all $y\in\mathbb{T}$,
\begin{equation}\label{thm0}
\int_{\mathbb{T}_{2\pi \kappa}}\omega_0(x,y)\,dx=0, \quad \int_{\mathbb{T}_{2 \pi \kappa} \times \mathbb{T} } \psi(t,x,y) \, dx dy = 0.
\end{equation}
Then we have the following bounds. 

(i) Inviscid damping estimates: For $u = \nabla^\perp \psi, $ 
\begin{equation}\label{th0.5}
\|\psi(t,\cdot)\|_{L^\infty(\mathbb{T}_{2\pi \kappa}\times \mathbb{T}) }\lesssim \frac{1}{\langle t\rangle^2}\|\omega_0\|_{H^4(\mathbb{T}_{2\pi \kappa}\times\mathbb{T})},
\end{equation}
\begin{equation}\label{thm1v}
\|u^x(t,\cdot)\|_{L^\infty(\mathbb{T}_{2\pi \kappa}\times\mathbb{T})}\lesssim \frac{1}{\langle t\rangle}\|\omega_0\|_{H^4(\mathbb{T}_{2\pi \kappa}\times\mathbb{T})}, \quad \|u^y(t,\cdot)\|_{L^\infty(\mathbb{T}_{2\pi \kappa}\times\mathbb{T})}\lesssim \frac{1}{\langle t\rangle^2}\|\omega_0\|_{H^4(\mathbb{T}_{2\pi \kappa}\times\mathbb{T})}. 
\end{equation} 

(ii) Vorticity depletion estimates: there exists a decomposition
\begin{equation}\label{thm1d}
\omega(t,x,y):=\omega_{\rm loc}(t,x,y)+\omega_{\rm nloc}(t,x,y),
\end{equation}
where for $(x,y,t)\in\mathbb{T}_{2\pi \kappa}\times\mathbb{T}\times[0,\infty)$,
\begin{equation}\label{thm3}
|\omega_{\rm loc}(t,x,y)|\lesssim \min ( |y-y_{1\ast}|^{2}, |y-y_{2\ast}|^{2} )\|\omega_0\|_{H^4(\mathbb{T}_{2\pi \kappa}\times\mathbb{T})},\quad |\omega_{\rm nloc}(t,x,y)|\lesssim \frac{1}{\langle t\rangle}\|\omega_0\|_{H^4(\mathbb{T}_{2\pi \kappa}\times\mathbb{T})}.
\end{equation}

\label{thm2}
Let $\kappa k \in \mathbb{Z} \setminus \{ 0\}$, $\theta \in (0, 1/4]$, $y \in \mathbb{T}$ and suppose that $(\psi_k, \omega_k)$  satisfy \eqref{F3.0}--\eqref{F3.0:elliptic} with $\omega_k(0,y) = \omega_{0k}(y)$. Then the following bounds hold.
\begin{subequations}
\label{main:bdd}
    \begin{align}
&|\psi_k(t,y)| \lesssim \langle t \rangle^{-2} |k|^{-3 + \theta} M_k, \label{damp1}
\\
&|\partial_y \psi_k(t,y)| \lesssim
\Bigl(
\langle t \rangle^{-3/2} |k|^{-5/2 + \theta}
+ \langle t \rangle^{-1} |b'|\, |k|^{-2 + \theta}
\Bigr) M_k, \label{damp2}\\
&|\omega_k(t,y)| \lesssim
\min\Bigl(
\langle t \rangle^{-1} |k|^{-2 + \theta}
+ |b'|^2 |k|^{-1 + \theta},
\; |k|^{-3 + \theta}
\Bigr) M_k, \label{depl1}
\\
&\bigl|\partial_y (e^{ik t b}\,\omega_k)(t,y)\bigr|
\lesssim
\min\Bigl(
\langle t \rangle^{-1/2} |k|^{-3/2 + \theta}
+ |b'|\, |k|^{-1 + \theta},
\; |k|^{-2 + \theta}
\Bigr) M_k, \label{pro1} \\
&\bigl|\partial_y (e^{ik t b}\,\psi_k)(t,y)\bigr|
\lesssim
\langle t \rangle^{-3/2} |k|^{-5/2 + \theta} M_k, \label{pro2}\\
&\bigl\| (\partial_y, k)^2 (e^{ik t b}\,\omega_k) \bigr\|_{L^2}
\lesssim
|k|^{-1 + \theta} M_k \label{pro3},
\end{align}
\end{subequations}
where $M_k = \norm{\omega_{0k}}_{H_k^4}$ (see \eqref{hk} for a definition of $H_k^4$).

\label{emb1}
 We call $\lambda\in\Sigma$ a generalized embedded eigenvalue, if one of the following conditions is satisfied. 
 \begin{itemize}
 \item  $\lambda$ is an embedded eigenvalue.
 
 \item $\lambda\neq b(y_{1*}), b(y_{2*})$ and there exists a nontrivial $\psi\in H^1(\mathbb{T}): \mathbb{T} \to \mathbb{C}$ such that in the sense of distributions,
 \begin{equation}\label{emb2}
 (k^2-\partial_y^2)\psi(y)+{\rm P.V.}\frac{b''(y)\psi(y)}{b(y)-\lambda}+i\pi\sum_{z\in \mathbb{T}, \,b(z)=\lambda}\frac{b''(z)\psi(z)}{|b'(z)|}\delta(y-z)=0.
 \end{equation}
 \end{itemize}

\label{F3.3}
 Suppose that $\kappa k\in\mathbb{Z}\backslash\{0\}$ and $\omega_{0k}\in L^2(\mathbb{T})$. Then the stream function $\psi_k(t,y)$ for $\kappa k\in\mathbb{Z}\backslash\{0\}, y\in \mathbb{T} , t\ge0$ has the representation 
 \begin{equation}\label{F3.4}
 \psi_k(t,y)=-\frac{1}{2\pi i}\lim_{\epsilon\to0+}\int_{\Sigma}e^{-ik\lambda t}\left[\psi_{k,\epsilon}^{-}(y,\lambda)-\psi_{k,\epsilon}^{+}(y,\lambda)\right]d\lambda,
 \end{equation}
 where $\psi_{k,\epsilon}^{\iota}(y,\lambda)$ for $\iota\in\{+,-\}, \,y\in \mathbb{T} ,\kappa k\in\mathbb{Z}\backslash\{0\}$,  and  sufficiently small $\epsilon\in[-1/4,1/4]\backslash\{0\}$, are the solutions to
 \begin{equation}\label{F7}
 \begin{split}
  \left(-\frac{d^2}{dy^2} + k^2+\frac{b''(y)}{b(y)-\lambda+i\iota\epsilon} \right) \psi_{k,\epsilon}^{\iota}(y,\lambda)=\frac{\omega_{0k}(y)}{b(y)-\lambda+i\iota\epsilon}.
 \end{split}
 \end{equation}

\label{mGk50} 

Let $\mathcal{G}^{j}_{k}(y,z;\Lambda)$ be defined as in \eqref{mGk1} for $j\in\{1,2\}, \lambda\in \Sigma_{j,\delta_0}$ and $0<|\epsilon|<\epsilon_0,\delta(\Lambda)\leq1/8.$ 
Then we have for $\beta\in\{0,1\}$ and $y, z\in\mathbb{T}$, $\mathcal{G}^j_{k}(y,z;\Lambda)=\mathcal{G}^j_{k}(z,y;\Lambda)$, and

\begin{equation}\label{mGk51}
\varrho_{j,k}^\beta(y;\Lambda) \big|\partial_y^{\beta}\mathcal{G}^j_{k}(y,z;\Lambda)\big| \lesssim  \varrho_{j,k}(z;\Lambda) \min\Big\{e^{-|k||y-z|}, \frac{\varrho_j^2(y;\Lambda)}{\varrho_j^2(z;\Lambda)},\,\frac{\varrho_j(z;\Lambda) }{\varrho_j(y;\Lambda)}\Big\}.
\end{equation}

\begin{comment}
                             
             
                                                                                                             
                                                                                                                                                                                           
           
              
\end{comment}

\label{mGk30}
Under the assumptions of Lemma \ref{mGk50},
 define for $y,z\in \mathbb{T}$,
 \begin{equation}\label{mGk31}
\mathcal{H}^j_k(y,z;\Lambda):=\Big[\partial_z+\chi_{j, 10\delta(\Lambda)}(y)\partial_y\Big]\mathcal{G}^j_{k}(y,z;\Lambda).
\end{equation}
Then we have the bounds for $y\in\mathbb{T}, z\in S^j_{4\delta(\Lambda)}$ and $\beta\in\{0,1\}$,
\begin{equation}\label{mGk52}
\begin{split}
&\varrho_{j,k}^\beta(y;\Lambda)\big|\partial_y^\beta\mathcal{H}^j_{k}(y,z;\Lambda)\big|\lesssim \min\Big\{e^{-|k||y-z|}, \frac{\varrho_j^2(y;\Lambda)}{\varrho_j^2(z;\Lambda)},\,\frac{\varrho_j(z;\Lambda) }{\varrho_j(y;\Lambda)}\Big\},
\end{split}
\end{equation}
and for $y,z\in\mathbb{T}$,
\begin{equation}\label{lem:mGK30:New}
\varrho_{j,k}^\beta(y;\Lambda)\big|\partial_y^\beta(\partial_z + \partial_y) \mathcal{G}^{j}_k(y,z;\Lambda) \big|\lesssim \min \left\{e^{-(|k|/2)|y-z|}, \frac{\varrho_{j,k}(y;\Lambda)}{\varrho_{j}(z;\Lambda)}, \frac{\varrho_{j,k}(z;\Lambda)}{\varrho_{j}(y;\Lambda)}    \right\}.
\end{equation}

\label{T2}
For  $\epsilon\in[-1/4,1/4]\backslash\{0\}, \lambda\in \Sigma\backslash \cup_{j} \Sigma_{j, \delta_0},  \kappa k\in\mathbb{Z}\backslash\{0\}$, the operator $T_\Theta$ satisfies the bound
\begin{equation}\label{T3}
\|T_\Theta g\|_{H^1_k(\mathbb{T})}\lesssim |k|^{-1/3}\|g\|_{H^1_k(\mathbb{T})},\qquad {\rm for\,\,all}\,\,g\in H^{1}_k(\mathbb{T}).
\end{equation}
In addition, we have the more precise regularity structure
\begin{equation}\label{T3.1}
\begin{split}
&\bigg\|\partial_yT_\Theta g(y)+\frac{b''(y)(1-\chi_{\ast,\delta_0/10})g(y)}{b'(y)}\log{(b(y)-\lambda+i\epsilon)}\bigg\|_{W^{1,1}(\mathbb{T})}\\
&\lesssim \langle k\rangle^{4/3}\|g\|_{H^1_k(\mathbb{T})}.
\end{split}
\end{equation}

\label{T5}
There exist $\epsilon_0, \mu_0>0$, such that the following statement holds. For all $\lambda\in \Sigma\backslash \cup_{j} \Sigma_{j, \delta_0}, \kappa k\in\mathbb{Z}\backslash\{0\}, 0<|\epsilon|<\epsilon_0$ and any $g\in H^1_k(\mathbb{T})$, we have the bound
\begin{equation}\label{T6}
\|g+T_\Theta g\|_{H^1_k(\mathbb{T})}\ge\mu_0 \|g\|_{H^1_k(\mathbb{T})}.
\end{equation}

\label{DeC4}
 For $0<|\epsilon|<\epsilon_0, \lambda\in\Sigma_{j,\delta_0},\,  \kappa k\in\mathbb{Z}\backslash\{0\},$ the operator $T_\Theta$ satisfies the bound for $X^{\sigma_1, \sigma_2}  $ with $\sigma_1 \in [0,1], \sigma_2 \in [-2,0], \sigma_1 + \sigma_2 \in [-2, 1]$,
\begin{equation}\label{DeC5}
\|T_\Theta g\|_{X^{\sigma_1, \sigma_2}}\lesssim (1 + |k| \delta(\Lambda))^{-1/4} \|g\|_{X^{\sigma_1, \sigma_2}},\quad {\rm for\,\,all}\,\,g\in H^{1}_k(\mathbb{T}) \cap W^{1, \infty}(\mathbb{T}).
\end{equation}
Additionally, we have the expansion
\begin{align}
\label{DeC6}
\partial_y T_\Theta g = -\chi_{j,\delta(\Lambda)}^*(y)\frac{b''(y)}{b'(y)}g(y)\log\frac{b(y)-\lambda+i\epsilon}{\delta^2(\Lambda)}+L_0(y,\lambda),
\end{align}
where $L_0$ satisfies the bounds 
\begin{align}
\label{DeC6.4}
  \norm{\partial_y L_0(y,\lambda)}_{L^1(S_{3 \delta(\Lambda)}^j)} \lesssim    
\frac{(\delta(\Lambda))^{-\sigma_1 - \sigma_2 }}{d_{j,k}}  \|g\|_{X^{\sigma_1, \sigma_2}}.
\end{align}

For simplicity of notation we drop $\Theta$ and decompose as 
\begin{equation}\label{DeC5.1}
T_\Theta  g(y):=T_1 g(y)+T_2g(y),
\end{equation}
where 
\begin{equation}\label{DeC5.2}
\begin{split}
&T_1g(y):=\int_{\mathbb{T}}\mathcal{G}_{k}^j(y,z;\Lambda)\bigg[1- \chi_{j, \delta_0}(z)\bigg]\frac{b''(z)g(z)}{b(z)-\lambda+i\epsilon}dz,\\
&T_2g(y):=\int_\mathbb{T} \mathcal{G}_{k}^j(y,z;\Lambda)\chi_{j,\delta_0\wedge\delta(\Lambda)}(z)\frac{b''(z)g(z)}{b(z)-\lambda+i\epsilon}dz.
\end{split}
\end{equation}
For the rest of the proof we assume $\delta(\Lambda)<\delta_0$, so that the cutoff in $T_2$ is $\chi_{j,\delta(\Lambda)}$. Otherwise, for $\delta(\Lambda)\geq\delta_0$ we have either $|\lambda-b(y_{j*})|\gtrsim\delta_0^2$ or $|\epsilon|\gtrsim\delta_0^2$. The conclusions \eqref{DeC5} and \eqref{DeC6.4} follow from similar calculations as in the non-degenerate case.

It follows from the bounds on modified Green's function $\mathcal{G}_{k}^j(y,z;\Lambda)$, the support of $1 - \chi_{j, \delta_0}(y)$, and $\lambda \in \Sigma_{j, \delta_0}$ that 
\begin{equation}\label{DeC13.4}
    \left|\varrho_{j,k}^\beta(y;\Lambda)\partial_y^\beta T_1g(y)\right|\lesssim\varrho_j^2(y;\Lambda)|k|^{-1}\|g\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0}^j)},
\end{equation}
\begin{equation}\label{DeC5.3}
\big\|T_1g\big\|_{X^{\sigma_1, \sigma_2}}\lesssim |k|^{-1/2}\big\|g\big\|_{X^{\sigma_1, \sigma_2}}.
\end{equation}
In addition, by \eqref{mGk1},
\begin{equation}\label{DeC5.3.1}
    \begin{split}
        \big\|\partial_y^2 T_1g\big\|_{L^1(S^j_{3\delta(\Lambda)})}\lesssim&(\delta(\Lambda))^{-2}(1+|k|\delta(\Lambda))^2\|T_1g\|_{L^1(S^j_{3\delta(\Lambda)})}\\
        \lesssim&\delta(\Lambda)(1+|k|\delta(\Lambda))^2|k|^{-1+\sigma_2}\|g\|_{X^{\sigma_1, \sigma_2}}\\
        \lesssim&\frac{(\delta(\Lambda))^{-\sigma_1 - \sigma_2 }}{d_{j,k}}  \|g\|_{X^{\sigma_1, \sigma_2}}.
    \end{split}
\end{equation}
To prove \eqref{DeC5}, it suffices to prove 
\begin{equation}\label{DeC5.4}
\|T_2g\|_{X^{\sigma_1, \sigma_2} }\lesssim  (1 + |k| \delta(\Lambda))^{-1/4}\|g\|_{X^{\sigma_1, \sigma_2}}.
\end{equation}
We assume momentarily that $|\epsilon|\lesssim |\lambda-b(y_{j\ast})|$ and explain how to remove this assumption at the end of the proof.  
We decompose further as
                                
               
                                                                                                                                                                   
                                                                                                                                          
                             
             
                
\begin{equation}\label{DeC5.5}
\begin{split}
T_2 g(y)&=\int_\mathbb{T} \mathcal{G}_{k}^j(y,z;\Lambda)  \chi_{j, c\delta(\Lambda)}(z)   \frac{b''(z)g(z)}{b(z)-\lambda+i\epsilon}dz\\
&+\int_\mathbb{T} \mathcal{G}_{k}^j(y,z;\Lambda) \chi_{j, \delta(\Lambda)}^*(z)\frac{b''(z)g(z)}{b(z)-\lambda+i\epsilon}dz\\
&:=T_{2,R}g(y)+T_{2,S}g(y),
\end{split}
\end{equation}
where $c=1/16$ in this section.
                                                                                                                                                                            
It suffices to prove for $\diamond\in\{R,S\}$
\begin{equation}\label{DeC5.50}
\|T_{2,\diamond}g\|_{X^{\sigma_1, \sigma_2}}\lesssim  (1 + |k| \delta(\Lambda))^{-1/4}\|g\|_{X^{\sigma_1, \sigma_2}}. 
\end{equation}


In the following process, one can simultaneously obtain the pointwise bounds on $T_2$ which will be used in Proposition~\ref{DeC7}. For $\delta(\Lambda)|k| \lesssim 1$, it yields
\begin{equation}\label{DeC10.3}
    \begin{split}
        \left|T_2g(y)\right|
                                                                                                                                                                                         
        \lesssim&\varrho_{j}^{-1}(y;\Lambda) \delta^{1/2}(\Lambda)\left[\|g\|_{L^2(S_{3\delta(\Lambda)}^j)}+\delta(\Lambda)\|\partial_y g\|_{L^2(S_{3\delta(\Lambda)}^j)}\right]\\
        \lesssim& \varrho_{j}^{-1}(y;\Lambda)\left(\delta(\Lambda)\right)^{1-\sigma_1-\sigma_2}\|g\|_{X^{\sigma_1,\sigma_2}},\qquad\ \text{for}\ y\in\mathbb{T}.
                                                                                                         
    \end{split}
\end{equation}
In addition,
\begin{equation}\label{DeC10.3.1}
\begin{aligned}
        &\left|\varrho_{j,k}(y;\Lambda)\partial_y T_2g(y)\right|
        \lesssim\varrho_{j}^{-1}(y;\Lambda) \delta^{1/2}(\Lambda)\left[\|g\|_{L^2(S_{3\delta(\Lambda)}^j)}+\delta\|\partial_y g\|_{L^2(S_{3\delta(\Lambda)}^j)}\right]\\
        &\hspace{31mm}\lesssim\varrho_{j}^{-1}(y;\Lambda)\left(\delta(\Lambda)\right)^{1-\sigma_1-\sigma_2}\|g\|_{X^{\sigma_1,\sigma_2}},\qquad\ \text{for}\ y\in\mathbb{T}\backslash S_{\delta(\Lambda)}^j;\\
        &\left\|\delta(\Lambda)\partial_y T_2g(y)\right\|_{L^2(S_{\delta(\Lambda)}^j)}\lesssim\|g\|_{L^2(S_{3\delta(\Lambda)}^j)}+\delta(\Lambda)\|\partial_y g\|_{L^2(S_{3\delta(\Lambda)}^j)}\lesssim \left(\delta(\Lambda)\right)^{1/2-\sigma_1-\sigma_2}\|g\|_{X^{\sigma_1,\sigma_2}}.
\end{aligned}
\end{equation}
{\bf Step 1.} We first prove \eqref{DeC5.50} with $\diamond=R$. 

{\it Case I: $\delta(\Lambda)|k| \lesssim 1 $}.  In this case for $|z-y_{j*}|\leq2c\delta(\Lambda)$  we have the bound 
\begin{equation}\label{DeC5.6}
\big|\mathcal{G}_{k}^j(y,z;\Lambda)\big|\lesssim \frac{\delta^2(\Lambda)}{\varrho_j(y; \Lambda)},\quad \big|\partial_y\mathcal{G}_{k}^j(y,z;\Lambda)\big|\lesssim\frac{\delta^2(\Lambda)}{\varrho_{j,k}(y; \Lambda) \varrho_j(y; \Lambda)  }. 
\end{equation}
It follows from the bound \eqref{DeC5.6} that 
\begin{equation}\label{DeC5.7}
\|T_{2,R}g\|_{X^{\sigma_1, \sigma_2 }}\lesssim \|g\|_{X^{\sigma_1, \sigma_2}}.
\end{equation}

{\it Case II: $\delta(\Lambda) |k| \gg 1$.} In this case, we have for $|z-y_{j*}|\leq2c\delta(\Lambda)$ that
\begin{equation}\label{DeC5.8}
\big|\mathcal{G}_{k}^j(y,z;\Lambda)\big|+|k|^{-1}\big|\partial_y\mathcal{G}_{k}^j(y,z;\Lambda)\big|\lesssim |k|^{-1}e^{-|k||y-z|}. 
\end{equation}
The desired bound 
\begin{equation}\label{DeC5.9}
\|T_{2,R}g\|_{X^{\sigma_1, \sigma_2}}\lesssim \big(1+|k|\delta(\Lambda)\big)^{-1/4}\|g\|_{X^{\sigma_1, \sigma_2}}
\end{equation}
follows from \eqref{DeC5.8}. 

Furthermore, we have 
\begin{equation}\label{DeC5.10}
    \begin{split}
        \big\|\partial_y^2 T_{2,R}g\big\|_{L^1(S^j_{3\delta(\Lambda)})}\lesssim&\left(\delta(\Lambda)\right)^{-2}(1+|k|\delta(\Lambda))^2\|T_{2,R}g\|_{L^1(S^j_{3\delta(\Lambda)})}+\left\|\chi_{j, c\delta(\Lambda)}(y)   \frac{b''(y)g(y)}{b(y)-\lambda+i\epsilon}\right\|_{L^1(S^j_{3\delta(\Lambda)})}\\
        \lesssim&\left[(1+|k|\delta(\Lambda))^2+ d_{j,k}^{-1}\delta(\Lambda)\right]\left(\delta(\Lambda)\right)^{-2-\sigma_1}d_{j,k}^{1-\sigma_2}\|g\|_{X^{\sigma_1, \sigma_2}}\\
        \lesssim&\frac{(\delta(\Lambda))^{-\sigma_1 - \sigma_2 }}{d_{j,k}}  \|g\|_{X^{\sigma_1, \sigma_2}}.
    \end{split}
\end{equation}
{\bf Step 2.} We now turn to the proof of \eqref{DeC5.50} with $\diamond=S$ and still consider two cases. 

{\it Case I: $\delta(\Lambda)|k| \lesssim 1$}.
 We can rewrite 
\begin{equation}\label{DeC6.2}
\begin{split}
T_{2,S}g(y)&=\int_\mathbb{T}\mathcal{G}_{k}^j(y,z;\Lambda)\chi_{j,\delta(\Lambda)}^\ast(z)\frac{b''(z)g(z)}{b'(z)}\partial_z\log{\frac{b(z)-\lambda+i\epsilon}{\delta^2(\Lambda)}}\,dz\\
&=-\int_\mathbb{T}\partial_z\bigg[\mathcal{G}_{k}^j(y,z;\Lambda)\chi_{j,\delta(\Lambda)}^\ast(z)\frac{b''(z)g(z)}{b'(z)}\bigg]\log{\frac{b(z)-\lambda+i\epsilon}{\delta^2(\Lambda)}}dz.
\end{split}
\end{equation}
As a consequence of \eqref{DeC6.2}, we also have
\begin{equation}\label{DeC6.3}
\begin{split}
\partial_y\Big[T_{2,S}g(y)\Big]&=\partial_y\int_\mathbb{T}\mathcal{G}_{k}^j(y,z;\Lambda)\chi_{j,\delta(\Lambda)}^\ast(z)\frac{b''(z)g(z)}{b'(z)}\partial_z\log{\frac{b(z)-\lambda+i\epsilon}{\delta^2(\Lambda)}}dz\\
&=-\int_\mathbb{T}\bigg[\partial_y(\partial_z+\partial_y)\mathcal{G}^j_{k}(y,z;\lambda,\epsilon)\chi_{j,\delta(\Lambda)}^\ast(z)\frac{b''(z)g(z)}{b'(z)}\bigg]\log{\frac{b(z)-\lambda+i\epsilon}{\delta^2(\Lambda)}}dz\\
&\quad+\int_\mathbb{T}\bigg[\partial^2_y\mathcal{G}_{k}^j(y,z;\Lambda)\chi_{j,\delta(\Lambda)}^\ast(z)\frac{b''(z)g(z)}{b'(z)}\bigg]\log{\frac{b(z)-\lambda+i\epsilon}{\delta^2(\Lambda)}}dz\\
&\quad-\int_\mathbb{T}\partial_y\mathcal{G}_{k}^j(y,z;\Lambda)\partial_z\bigg[\chi_{j,\delta(\Lambda)}^\ast(z)\frac{b''(z)g(z)}{b'(z)}\bigg]\log{\frac{b(z)-\lambda+i\epsilon}{\delta^2(\Lambda)}}dz.
\end{split}
\end{equation}
Note that on the support of $\chi_{j,\delta(\Lambda)}^\ast(z)$, we have 
\begin{equation}\label{DeC6.31}
|b'(z)|\approx \delta(\Lambda), \quad \varrho_j(z; \Lambda)\approx \delta(\Lambda).
\end{equation}
The desired bound \eqref{DeC5.50} for $\diamond=S$ follows from \eqref{DeC6.2}-\eqref{DeC6.3}, Lemmas \ref{mGk50}, \ref{mGk30} and we have, in addition,
\begin{equation}\label{Dec6.32}
\begin{split}
&(\delta(\Lambda))^{-1}\bigg\|\partial_y\bigg\{\partial_yT_{2,S}g(y)+\chi_{j,\delta(\Lambda)}^*(y)\frac{b''(y)g(y)}{b'(y)}\log{\frac{b(y)-\lambda+i\epsilon}{\delta^2(\Lambda)}}\bigg\}\bigg\|_{L^1(S_{3 \delta(\Lambda)}^j)}\\
&\lesssim\delta(\Lambda)^{-\sigma_1 - \sigma_2 -2} \Big[1+|k|\delta(\Lambda)\Big]^{-1/4}\|g\|_{X^{\sigma_1, \sigma_2}}.
\end{split}
\end{equation}

{\it Case II: $\delta(\Lambda) |k| \gg 1$.} This case is analogous to {\it Case I}, using Lemmas \ref{mGk50}, \ref{mGk30}. 

Finally, it remains to consider $|\epsilon|\geq|\lambda-b(y_{j*})|$. In this case $\delta^2(\Lambda)\approx|\epsilon|$, and 
\begin{align*}
|b(z)-\lambda+i\epsilon|\approx |z-y_{j*}|^2+|\epsilon|
\approx\varrho_j^2(z;\Lambda),\qquad |z-y_{j*}|\leq2\delta_0.
\end{align*}
In particular, on the support of $\chi_{j,\delta(\Lambda)}$, the reciprocal denominator is $O(\delta^{-2}(\Lambda))$ and the normalized logarithm is bounded. Each spatial derivative costs at most another factor $\delta^{-1}(\Lambda)$. Combining these bounds with Lemma~\ref{mGk50} gives \eqref{DeC5.4}. By similar estimates as in \eqref{DeC5.10}, we have the following bound
\begin{equation}\label{Dec6.33}
    \big\|\partial_y^2 T_2g\big\|_{L^1(S^j_{3\delta(\Lambda)})}\lesssim\frac{(\delta(\Lambda))^{-\sigma_1 - \sigma_2 }}{d_{j,k}}  \|g\|_{X^{\sigma_1, \sigma_2}},
\end{equation}
which gives \eqref{DeC6.4}. Thus both epsilon regimes are covered.

\label{DeC7}
 For $\sigma_1 \in [0,1], \sigma_2 \in [-2,0], \sigma_1 + \sigma_2 \in [-2, 1]$, there exist positive numbers $\epsilon_0, \mu_0$ such that   the following statement holds. For $\epsilon\in[-\epsilon_0,\epsilon_0]\backslash\{0\}$, $\lambda\in \cup_{j}\Sigma_{j, \delta_0}$,  $\kappa k\in\mathbb{Z}\backslash\{0\}$ we have
\begin{equation}\label{DeC8}
\|(I+T_\Theta) g\|_{X^{\sigma_1, \sigma_2}}\ge \mu_0\| g\|_{X^{\sigma_1, \sigma_2}}, \quad {\rm for\,\,all}\,\,g\in H^{1}_k(\mathbb{T}) \cap W^{1, \infty}(\mathbb{T}).
\end{equation}

We prove \eqref{DeC8} by a contradiction argument.  Assume \eqref{DeC8} does not hold for any $\epsilon_0>0$. Since there are only two degenerate spectral neighborhoods, we may choose the contradiction sequence below in a fixed $\Sigma_{j,\delta_0}$. Then there exist for $\ell\in\mathbb{Z}\cap[1,\infty)$,
    \begin{equation}\label{DeC9}
        \lambda_\ell\to\lambda_\ast\in \Sigma_{j,\delta_0}, \,\,\epsilon_\ell\neq0 \,\,{\rm with}\,\,\epsilon_\ell\to0, \,\,\kappa k_\ell\to \kappa k_\ast\in (\mathbb{Z}\backslash\{0\})\cup\{\pm\infty\},
    \end{equation}
    and functions $g_\ell$ satisfying
    \begin{equation}\label{DeC9.1}
        \|g_\ell\|_{X^{\sigma_1, \sigma_2}(\mathbb{T})}=1,
    \end{equation} 
    such that 
    \begin{equation}\label{DeC10}
        \big\|(I+T_{\Theta_\ell}(\lambda_\ell+i\epsilon_\ell))g_\ell\big\|_{X^{\sigma_1, \sigma_2}(\mathbb{T})}\to 0\quad\ \text{as}\ \ell\to\infty.
    \end{equation}
    We can assume that $\lambda_\ast=b(y_{j\ast})$, otherwise the proof follows from the arguments in the non-degenerate case, see Lemma 4.2 in \cite{IIJ24}. For convenience, we use the shorthand $\delta_\ell:=\delta(\Lambda_\ell)$, which tends to zero as $\ell\to\infty$ by \eqref{DeC9}.
    By Lemma \ref{DeC4}, it suffices to consider $|k_\ell|\delta_\ell\lesssim 1$. 
    We consider the following cases.

    {\it Case I: $\limsup_{\ell\to\infty}\sum_{\beta\in\{0,1\}}\|\varrho_{j,k_\ell}^{\beta}(\cdot;\Lambda_\ell)\partial_y^\beta g_\ell\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0})}=0$.} In this case,  we assert that (passing to a subsequence if necessary)
    \begin{equation}\label{DeC13}
        \|\delta_\ell^{\sigma_1+\sigma_2-1/2}g_\ell\|_{L^2(S_{3\delta_\ell})}+\|\delta_\ell^{\sigma_1+\sigma_2+1/2}\partial_y g_\ell\|_{L^2(S_{3\delta_\ell})}\geq\sigma>0.
    \end{equation}
                                   
                       
                                                                                                                                                                                                                     
                                                                                                                                                                                                                                           
                     
                    
    Otherwise, if
    \begin{equation}\label{DeC13.1}
        \limsup_{\ell\to\infty}\|\delta_\ell^{\sigma_1+\sigma_2-1/2}g_\ell\|_{L^2(S_{3\delta_\ell})}+\|\delta_\ell^{\sigma_1+\sigma_2+1/2}\partial_y g_\ell\|_{L^2(S_{3\delta_\ell})}=0,
    \end{equation}
    together with \eqref{DeC13.4}, \eqref{DeC5.3}, \eqref{DeC10.3} and the Case I assumption, we would obtain
    \begin{align}\label{DeC13.2}
        \|T_1g_\ell\|_{X^{\sigma_1,\sigma_2}},\, \|T_2g_\ell\|_{X^{\sigma_1,\sigma_2}}\to 0\quad\  \text{as}\ \ell\to\infty.
    \end{align}
    Thus, combining \eqref{DeC10}, we have 
    \begin{equation}\label{DeC13.3}
        \|g_\ell\|_{X^{\sigma_1,\sigma_2}}\lesssim\|(I+T_{\Theta_\ell})g_\ell\|_{X^{\sigma_1,\sigma_2}}+\|T_1g_\ell\|_{X^{\sigma_1,\sigma_2}}+\|T_2 g_\ell\|_{X^{\sigma_1,\sigma_2}}\to 0\quad\  \text{as}\ \ell\to\infty,
    \end{equation}
    contradicting \eqref{DeC9.1}.
                                                                                                                                                                                                                                                  
                      
                                                                                                                                                                                                                                                            
                    
                                       
                      
                                                                                                                                                                                                                                                                                   
                    
                                                                                                                                                                                                                     
                      
                                                                                                                                                                                                                                   
                    
    

    Now, under \eqref{DeC13}, recall from \eqref{Intd1} that
    \begin{equation}\label{DeC14}
        \delta_\ell\approx|\epsilon_\ell|^{1/2}+|\lambda_\ell-b(y_{j\ast})|^{1/2}. 
    \end{equation}
    We divide into several subcases.

    {\it Subcase I.1: $|\epsilon_\ell|^{1/2}\approx |\lambda_\ell-b(y_{j\ast})|^{1/2}$ for a subsequence.}
    Define the change of variables for $\ell\ge1, y\in \mathbb{T}$,
    \begin{equation}\label{DeC15}
        y-y_{j\ast}=s_\ell Y, \quad g_\ell(y):=\delta_\ell^{-\sigma_1-\sigma_2}H_\ell(Y). 
    \end{equation}
    In this subcase, take the scale $s_\ell=|\lambda_\ell-b(y_{j\ast})|^{1/2}$.
    It follows from \eqref{DeC6}-\eqref{DeC6.4} that we can extract a nontrivial limit $H\in H^1(\mathbb{R})$ of $H_\ell$ satisfying for $Y\in \mathbb{R}$,
    \begin{equation}\label{DeC16}
        (\beta^2-\partial_Y^2)H(Y)+\frac{b''(y_{j\ast})}{b''(y_{j\ast})Y^2/2+\gamma+i\alpha}H(Y)=0,
    \end{equation}
    where $\beta=\lim_{\ell\to\infty}|k_\ell||\lambda_\ell-b(y_{j\ast})|^{1/2}\in\mathbb{R}, \alpha=\lim_{\ell\to\infty}\epsilon_\ell|\lambda_\ell-b(y_{j\ast})|^{-1}, \gamma={\rm{sgn}}(b(y_{j\ast})-\lambda_\ell)\in\mathbb{R}\backslash\{0\}.$ This is impossible since the shear flow $(b''(y_{j\ast})Y^2/2,0), Y\in\mathbb{R}$ is spectrally stable. 
    
    To obtain this, we first prove the local convergence. More specifically, for any fixed $L$, 
    \begin{equation}
        \begin{split}
            \|H_\ell\|_{L^2(-L,L)}=\delta_\ell^{\sigma_1+\sigma_2}s_\ell^{-1/2}\|g_\ell\|_{L^2(S_{Ls_\ell})},\\
            \|\partial_Y H_\ell\|_{L^2(-L,L)}=\delta_\ell^{\sigma_1+\sigma_2}s_\ell^{1/2}\|\partial_y g_\ell\|_{L^2(S_{Ls_\ell})}.\\
        \end{split}
    \end{equation}
    By \eqref{DeC9.1}, we have 
    \begin{equation}\label{DeC16.0}
        \sup_{\ell}\|H_\ell\|_{H^1(-L,L)}\lesssim_{L}1,\quad\ \text{for every fixed }\ L.
    \end{equation}
    Furthermore, we assert 
    \begin{equation}\label{Dec16.1}
    \left\|\frac{T_{\Theta_\ell}(\lambda_\ell+i\epsilon_\ell)g_\ell(y_{j\ast}+s_\ell Y)}{\delta_\ell^{-\sigma_1-\sigma_2}}\right\|_{W^{2,1}_Y([-L,L])}\lesssim1.
    \end{equation}
    Then by \eqref{DeC10}, 
    \begin{equation}\label{Dec16.1.01}
        \left\|H_\ell+\frac{T_{\Theta_\ell}(\lambda_\ell+i\epsilon_\ell)g_\ell(y_{j\ast}+s_\ell Y)}{\delta_\ell^{-\sigma_1-\sigma_2}}\right\|_{H^1_Y([-L,L])}\to 0\quad\  \text{as}\ \ell\to\infty,
    \end{equation}
    which provides strong convergence $H_\ell\to H$ in $H^1_{\rm{loc}}(\mathbb{R})$.
    For relatively regular operators $T_1$, $T_{2,R}$, their local $H^2$ estimates are straightforward: For any fixed $L\geq 1$, $y\in S_{Ls_\ell}$,
    \begin{align}
        &\partial_y^2 T_1 g_\ell=k^2 T_1 g_\ell+\frac{b''(y)}{b(y)-\lambda_\ell+i\epsilon_\ell}\left(1-\chi_{j,\delta_\ell}\right)T_1g_\ell,\\
        &\partial_y^2 T_{2,R} g_\ell=k^2 T_{2,R} g_\ell+\frac{b''(y)}{b(y)-\lambda_\ell+i\epsilon_\ell}\left(1-\chi_{j,\delta_\ell}\right)T_{2,R} g_\ell-\chi_{j,\delta_\ell}\chi_{j,c\delta_\ell}\frac{b''(y)}{b(y)-\lambda_\ell+i\epsilon_\ell}g_\ell.
    \end{align}
    Since $|\epsilon_\ell|^{1/2}\approx \delta_\ell$ and $|k_\ell|\lesssim \delta_\ell^{-1}$, 
    \begin{equation}\label{Dec16.1.1}
        |b(y)-\lambda_\ell+i\epsilon_\ell|^{-1}\lesssim|\epsilon_\ell|^{-1}\lesssim\delta_\ell^{-2}.
    \end{equation}
    Combining \eqref{DeC5.3} and \eqref{DeC5.50}, we have 
    \begin{align}
        &\|\partial_y^2 T_1 g_\ell\|_{L^2(S_{Ls_\ell})}\lesssim\delta_\ell^{-2}\|T_1 g_\ell\|_{L^2(S_{Ls_\ell})}\lesssim \delta_\ell^{-\sigma_1-\sigma_2-3/2}|k_\ell|^{-1/2}\|g_\ell\|_{X^{\sigma_1,\sigma_2}},\\
        &\|\partial_y^2 T_{2,R} g_\ell\|_{L^2(S_{Ls_\ell})}\lesssim\delta_\ell^{-2}\left(\|T_{2,R} g_\ell\|_{L^2(S_{Ls_\ell})}+\|g_\ell\|_{L^2(S_{Ls_\ell})}\right)\lesssim \delta_\ell^{-\sigma_1-\sigma_2-3/2}\|g_\ell\|_{X^{\sigma_1,\sigma_2}}.
    \end{align}
                      
                
                                                                           
                                         
                                                     
                                                         
              
Therefore, by \eqref{DeC9.1} and the rescaling \eqref{DeC15},
\begin{align}
&\left\|\partial_Y^2\left(\frac{T_1g_\ell(y_{j\ast}+s_\ell Y)}{\delta_\ell^{-\sigma_1-\sigma_2}}\right)\right\|_{L^2_Y([-L,L])}\lesssim s_\ell^{3/2}\delta_\ell^{\sigma_1+\sigma_2}\|\partial_y^2T_1g_\ell\|_{L^2(S_{Ls_\ell})}\lesssim |k_\ell|^{-1/2},\label{Dec16.2}\\
&\left\|\partial_Y^2\left(\frac{T_{2,R}g_\ell(y_{j\ast}+s_\ell Y)}{\delta_\ell^{-\sigma_1-\sigma_2}}\right)\right\|_{L^2_Y([-L,L])}\lesssim s_\ell^{3/2}\delta_\ell^{\sigma_1+\sigma_2}\|\partial_y^2T_{2,R}g_\ell\|_{L^2(S_{Ls_\ell})}\lesssim 1.\label{Dec16.3}
\end{align}

                                     
{\color{black}
For this application of \eqref{Dec6.32}, its integration interval may
be enlarged to $S^j_{Ls_\ell}$, with a constant depending on fixed $L$.
Indeed, set $a=\sigma_1+\sigma_2$ and $u_\ell=T_{2,S}g_\ell$.
On $S^j_{Ls_\ell}\setminus S^j_{3\delta_\ell}$ the source and logarithmic
correction vanish. Since $s_\ell\approx\delta_\ell$ and
$|k_\ell|\delta_\ell\lesssim1$, \eqref{mGk1} and \eqref{DeC5.50} give
\[
 |u_\ell''|\lesssim_L\delta_\ell^{-2}|u_\ell|,
 \qquad
 \|u_\ell''\|_{L^1(S^j_{Ls_\ell}\setminus S^j_{3\delta_\ell})}
 \lesssim_L\delta_\ell^{-a-1}\|g_\ell\|_{X^{\sigma_1,\sigma_2}}.
\]
Multiplication by the rescaling factor $\delta_\ell^a s_\ell$ gives
the required $O_L(1)$ bound on the added annulus.
\par}
                                   
By \eqref{Dec6.32}, $T_{2,S}$ is controlled in $W^{2,1}$ after extracting the logarithmic singularity, namely
\begin{equation}\label{DeC16.4}
\begin{aligned}
&\left\|\partial_Y^2\left(\frac{T_{2,S}g_\ell(y_{j\ast}+s_\ell Y)}{\delta_\ell^{-\sigma_1-\sigma_2}}\right)\right.\\
&\qquad\quad\left.+s_\ell\partial_Y\left\{\chi_{j,\delta_\ell}^*(y_{j\ast}+s_\ell Y)\frac{b''(y_{j\ast}+s_\ell Y)H_\ell(Y)}{b'(y_{j\ast}+s_\ell Y)}\log\frac{b(y_{j\ast}+s_\ell Y)-\lambda_\ell+i\epsilon_\ell}{\delta_\ell^2}\right\}\right\|_{L^1_Y([-L,L])}\\
&\lesssim \delta_\ell^{\sigma_1+\sigma_2}s_\ell
\left\|\partial_y\left\{\partial_yT_{2,S}g(y)+\chi_{j,\delta_\ell}^*(y)\frac{b''(y)g(y)}{b'(y)}
\log\frac{b(y)-\lambda_\ell+i\epsilon_\ell}{\delta_\ell^2}\right\}\right\|_{L_y^1(S_{Ls_\ell}^j)}\\
&\lesssim1.
\end{aligned}
\end{equation}
Under the assumption $|\epsilon_\ell|^{1/2}\approx\delta_\ell$, the logarithmic singularity satisfies
\begin{equation}
\begin{split}
    &\left\|s_\ell \chi_{j,\delta_\ell}^*(y_{j\ast}+s_\ell Y)\frac{b''(y_{j\ast}+s_\ell Y)H_\ell(Y)}{b'(y_{j\ast}+s_\ell Y)}\log\frac{b(y_{j\ast}+s_\ell Y)-\lambda_\ell+i\epsilon_\ell}{\delta_\ell^2}\right\|_{H^1_Y([-L,L])}\\
    &\lesssim\|H_\ell\|_{H^1_Y([-L,L])}\lesssim1.
\end{split}
\end{equation}
     
                  
                 
                                                                                                                                                                                                                           
                                               
                                                                         
               
                
Together with \eqref{Dec16.2} and \eqref{Dec16.3}, we proved \eqref{Dec16.1}. 
                                                                                                    
                                 
                                                                             
                
                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                  
                   
                                                                                                                                                                                                              
                                                                                                                                              
                 
                
                                                                    
                  
                                                                                                                                                                                                                             
                
             
                  
                                                                                                                        
                
                                                                                                                                                                                                                      
               
                                                                                                                                                                                                 
                                                                                                                                                                                                                                                              
             
Finally, under assumptions for Case I and Subcase I.1, as $\ell\to\infty$,
\begin{align}
    &\left|\delta_\ell^{\sigma_1+\sigma_2}T_1g_\ell(y_{j\ast}+s_\ell Y)\right|\lesssim(|Y|+1)^2\delta_\ell^{2+\sigma_1+\sigma_2}|k_\ell|^{-1}\|g_\ell\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0})}\to 0,\label{DeC16.6}\\
    &\left|\delta_\ell^{\sigma_1+\sigma_2}T_2g_\ell(y_{j\ast}+s_\ell Y)\right|\lesssim(|Y|+1)^{-1}\|g_\ell\|_{X^{\sigma_1,\sigma_2}}\to (|Y|+1)^{-1}.
\end{align}
Combining this with the consequence 
\begin{equation}
    \left|\delta_\ell^{\sigma_1+\sigma_2}\left(I+T_{\Theta_\ell}\right)g_\ell(y_{j\ast}+s_\ell Y)\right|\lesssim\|\left(I+T_{\Theta_\ell}\right)g_\ell\|_{X^{\sigma_1,\sigma_2}}\to0,
\end{equation}
of \eqref{DeC10}, we obtain
\begin{equation}\label{DeC16.7}
    |H(Y)|=\lim_{\ell\to\infty}|H_\ell(Y)|\lesssim(|Y|+1)^{-1}.
\end{equation}
                                                                         
Thus, $H\in H^1(\mathbb{R})$. The contradiction argument based on \eqref{DeC16} then follows.

{\it Subcase I.2: $|\epsilon_\ell|^{1/2}=o\left( |\lambda_\ell-b(y_{j\ast})|^{1/2}\right)$ for a subsequence.} Passing to a subsequence and using the same rescaling \eqref{DeC15} with $s_\ell=|\lambda_\ell-b(y_{j\ast})|^{1/2}$, we can extract a nontrivial limit $H\in H^1(\mathbb{R})$, such that 
\begin{equation}\label{DeC17}
    (\beta^2-\partial_Y^2)H(Y)+\lim_{\epsilon\to0}\frac{b''(y_{j\ast})}{b''(y_{j\ast})Y^2/2+\gamma+i\epsilon}H(Y)=0,
\end{equation}
where $\epsilon=\epsilon_\ell|\lambda_\ell-b(y_{j\ast})|^{-1}\to 0$ as $\ell\to\infty$. This is again impossible since the shear flow $(b''(y_{j\ast})Y^2/2,0), Y\in\mathbb{R}$ is spectrally stable and has no embedded eigenvalues.

More precisely, in this subcase \eqref{Dec16.2} and \eqref{Dec16.3} still hold, but instead of controlling the singularity by $|\epsilon_\ell|$ as in \eqref{Dec16.1.1}, we use the fact that for $y\in{\rm{supp}}(1-\chi_{j,\delta_\ell})\cup{\rm{supp}}(\chi_{j,c\delta_\ell})$,
\begin{equation}
    |b(y)-\lambda_\ell+i\epsilon_\ell|^{-1}\lesssim|b(y_{j\ast})-\lambda_\ell|^{-1}\lesssim\delta_\ell^{-2}.
\end{equation}
For the operator $T_{2,S}$, we no longer prove its $H^2$ boundedness. Instead, \eqref{DeC16.0} gives $H_\ell\to H$ uniformly on every compact interval by the Sobolev embeddings $H^1\Subset C^{0}$. Then 
\begin{equation}
s_\ell \chi_{j,\delta_\ell}^*(y_{j\ast}+s_\ell Y)\frac{b''(y_{j\ast}+s_\ell Y)H_\ell(Y)}{b'(y_{j\ast}+s_\ell Y)}\log\frac{b(y_{j\ast}+s_\ell Y)-\lambda_\ell+i\epsilon_\ell}{\delta_\ell^2}
\end{equation}
converges strongly in $L^2_{\rm loc}$. Meanwhile, \eqref{DeC16.4} gives strong $L^2_{\rm loc}$ convergence for the remainder
\begin{equation}
\partial_Y\left(\frac{T_{2,S}g_\ell(y_{j\ast}+s_\ell Y)}{\delta_\ell^{-\sigma_1-\sigma_2}}\right)+s_\ell \chi_{j,\delta_\ell}^*(y_{j\ast}+s_\ell Y)\frac{b''(y_{j\ast}+s_\ell Y)H_\ell(Y)}{b'(y_{j\ast}+s_\ell Y)}\log\frac{b(y_{j\ast}+s_\ell Y)-\lambda_\ell+i\epsilon_\ell}{\delta_\ell^2}.
\end{equation}
Thus, the rescaled $\partial_Y T_{2,S}$ strongly converges in $L^2_{\rm{loc}}$, which means $T_{2,S}$ strongly converges in $H^1_{\rm{loc}}$. Together with \eqref{Dec16.1.01}, this yields \eqref{DeC17}. $H\in H^1(\mathbb{R})$ follows from the same arguments as in Subcase I.1.

{\it Subcase I.3: $|\lambda_\ell-b(y_{j*})|^{1/2}=o(|\epsilon_\ell|^{1/2})$ for a subsequence. } 
In this case, we follow a slightly different rescaling \eqref{DeC15} with $s_\ell=|\epsilon_\ell|^{1/2}$.
                               
                                                                                                      
                
Then similar arguments as in Subcase I.1 yield \eqref{Dec16.2}-\eqref{DeC16.7}.
                  
                   
                                                                                                                                       
                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                      
                                                                                                     
                 
                
      
                  
                   
                                                                                                                                                                                                                                           
                                                             
                 
                
                             
               
                                                                                                                                                                                                                
                                                                                                                                                                
             
Thus, we can extract a nontrivial limit $H\in H^1(\mathbb{R})$ of $H_\ell$ satisfying for $Y\in \mathbb{R}$,
    \begin{equation}\label{DeC18.1}
        (\beta^2-\partial_Y^2)H(Y)+\lim_{\gamma\to 0}\frac{b''(y_{j\ast})}{b''(y_{j\ast})Y^2/2+\gamma+i\alpha}H(Y)=0,
    \end{equation}
    where $\beta=\lim_{\ell\to\infty}|k_\ell||\epsilon_\ell|^{1/2}\in\mathbb{R}, \alpha={\rm{sgn}}\epsilon_\ell \in\mathbb{R}\backslash\{0\}, \gamma=\lim_{\ell\to\infty}(b(y_{j\ast})-\lambda_\ell)\cdot|\epsilon_\ell|^{-1}.$ This is impossible since the shear flow $(b''(y_{j\ast})Y^2/2,0), Y\in\mathbb{R}$ is spectrally stable. 





    \medskip
    {\it Case II: $\limsup_{\ell\to\infty}\sum_{\beta\in\{0,1\}}\|\varrho_{j,k_\ell}^{\beta}(\cdot;\Lambda_\ell)\partial_y^\beta g_\ell\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0})}>0$.} 
    
    {\it Subcase II.1:} For $(\sigma_1,\sigma_2)\neq (1,0)$, we can directly assume that $\kappa k_*\in\mathbb{Z}\backslash\{0\}$. 
    Otherwise, $|k_\ell|\to\infty$ would bring $\varrho_{j,k_\ell}(y;\Lambda_\ell)=|k_\ell|^{-1}$ for any fixed $y$. Then by \eqref{DeC1}, \eqref{DeC5.3} and $\sigma_2\leq 0$,
    \begin{equation}\label{DeC10.1}
        \sum_{\beta\in\{0,1\}}\|\varrho_{j,k_\ell}^{\beta}(\cdot;\Lambda_\ell)\partial_y^\beta T_1 g_\ell\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0})}\leq|k_\ell|^{\sigma_2}\|T_1g_\ell\|_{X^{\sigma_1,\sigma_2}}\lesssim|k_\ell|^{\sigma_2-1/2}\|g_\ell\|_{X^{\sigma_1,\sigma_2}}\to 0,
    \end{equation}
    as $\ell\to\infty$.
    Meanwhile, we claim that 
    \begin{equation}\label{DeC10.2}
        \sum_{\beta\in\{0,1\}}\|\varrho_{j,k_\ell}^{\beta}(\cdot;\Lambda_\ell)\partial_y^\beta T_2g_\ell\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0})}\to 0\quad\  \text{as}\ \ell\to\infty.
    \end{equation}
    Indeed, it follows from \eqref{DeC5.4} when $\delta_\ell|k_\ell|\gg1$, and from \eqref{DeC10.3}-\eqref{DeC10.3.1} with the assumption $\sigma_1+\sigma_2<1$ in this subcase when $\delta_\ell|k_\ell|\lesssim1$. 
                                                   
                                     
                       
                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                      
                                                                                                                
                                                                                                                    
                     
                    
                                                                                       
             
                      
                                                                                                                                       
                    
                      
                                                                                                                                                                                                                                
                    
    Furthermore, by \eqref{DeC10} and $\sigma_2\leq 0$,
    \begin{equation}\label{DeC10.4}
\begin{aligned}
&\sum_{\beta\in\{0,1\}}\|\varrho_{j,k_\ell}^{\beta}(\cdot;\Lambda_\ell)\partial_y^\beta(I+T_{\Theta_\ell})g_\ell\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0})}\\
&\quad\lesssim\delta_0^{-\sigma_1}|k_\ell|^{\sigma_2}\big\|(I+T_{\Theta_\ell})g_\ell\big\|_{X^{\sigma_1,\sigma_2}(\mathbb{T})}
\to0\quad\text{as }\ell\to\infty.
\end{aligned}
    \end{equation}
    Combining \eqref{DeC10.1}, \eqref{DeC10.2} and \eqref{DeC10.4}, we have as $\ell\to\infty$,
    \begin{equation}
        \begin{split}
            &\sum_{\beta\in\{0,1\}}\|\varrho_{j,k_\ell}^{\beta}(\cdot;\Lambda_\ell)\partial_y^\beta g_\ell\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0})}\\
            &\lesssim\sum_{\beta\in\{0,1\}}\left(\|\varrho_{j,k_\ell}^{\beta}(\cdot;\Lambda_\ell)\partial_y^\beta(I+T_{\Theta_\ell})g_\ell\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0})}+\|\varrho_{j,k_\ell}^{\beta}(\cdot;\Lambda_\ell)\partial_y^\beta T_1g_\ell\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0})}\right.\\
            &\hspace{20mm}+\left.\|\varrho_{j,k_\ell}^{\beta}(\cdot;\Lambda_\ell)\partial_y^\beta T_2g_\ell\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0})}\right)\\
            &\to 0,
        \end{split}
    \end{equation}
    contradicting our non-concentration assumption. By \eqref{DeC9.1}, \eqref{DeC10}, we can assume (passing to a subsequence if necessary) that 
    \begin{equation}\label{DeC11}
        g_\ell\to g, \,\,{\rm in}\,\, H^1_{{\rm loc}}(\mathbb{T}\backslash \{y_{j\ast}\})\,\,{\rm as}\,\,\ell\to\infty.
    \end{equation}
    Then one can obtain that $g$ satisfies
    \begin{equation}\label{DeC11.1}
        |g(y)|\lesssim |y-y_{j\ast}|^{2},
    \end{equation}
    and for $y\in \mathbb{T}$, in the $L^2$ sense,
    \begin{equation}\label{DeC12}
        (k_\ast^2-\partial_y^2)g(y)+\frac{b''(y)}{b(y)-b(y_{j\ast})}g(y)=0.
    \end{equation}
    In fact, for any fixed $\mathfrak{d}>0$, we have $2\delta_{\ell}<\mathfrak{d}$ for sufficiently large $\ell$. In the compact domain $\mathbb{T}\backslash S_\mathfrak{d}$, $\chi_{j,\delta}\equiv 0$, so $T_{\Theta_\ell}g(y)$ satisfies the simplified equation
    \begin{equation}\label{DeC12.1}
        \begin{split}
            \partial_y^2 T_{\Theta_\ell}g_{\ell}=\left\{k_\ell^2+\frac{b''(y)\chi_{j,\delta_0}}{b(y)-\lambda_\ell+i\epsilon_\ell}\right\}T_{\Theta_\ell}g_{\ell}-(1-\chi_{j,\delta_0})\frac{b''(y)g_\ell(y)}{b(y)-\lambda_\ell+i\epsilon_\ell}, 
        \end{split}
    \end{equation}
    with the following bounds independent of $\ell$:
    \begin{align}
        &\|T_{\Theta_\ell}g_\ell\|_{L^\infty(\mathbb{T}\backslash S_\mathfrak{d})}\lesssim_{\mathfrak{d}}\|T_{\Theta_\ell}g_\ell\|_{X^{\sigma_1,\sigma_2}}\lesssim_{\mathfrak{d}}1,\\
        &\|g_\ell\|_{L^\infty(\mathbb{T}\backslash S_\mathfrak{d})}\lesssim_{\mathfrak{d}}\|g_\ell\|_{X^{\sigma_1,\sigma_2}}\lesssim_{\mathfrak{d}}1,\\
        &\left|b(y)-\lambda_\ell+i\epsilon_\ell \right|^{-1}\lesssim |\mathfrak{d}|^{-2}.
    \end{align}
    Therefore, 
    \begin{equation}\label{DeC12.2}
        \limsup_{\ell\to \infty}\|T_{\Theta_\ell}(\lambda_\ell+i\epsilon_{\ell})g_\ell\|_{W^{2,\infty}(\mathbb{T}\backslash S_\mathfrak{d})}\lesssim_{\mathfrak{d}}1.
    \end{equation}
    By Sobolev embeddings, $T_{\Theta_\ell}(\lambda_\ell+i\epsilon_{\ell})g_\ell$ converges strongly in $H^1_{{\rm loc}}(\mathbb{T}\backslash \{y_{j\ast}\})$. Together with \eqref{DeC10}, we obtain \eqref{DeC11}.
    Moreover, by \eqref{DeC10} and \eqref{DeC10.3}, 
    \begin{equation}
        \lim_{\ell\to\infty}T_2g_\ell=0,\quad\ g+ \lim_{\ell\to\infty}T_1g_\ell=0\qquad\ \text{in}\ H^1_{\rm{loc}}(\mathbb{T}\backslash \{y_{j\ast}\}).
    \end{equation}
    By \eqref{DeC5.2}
    \begin{equation}
        \left|T_1g_\ell(y)\right|\lesssim\varrho_{j}^2(y;\Lambda_\ell)|k_\ell|^{-1}\|g_\ell\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0})}\lesssim\varrho_{j}^2(y;\Lambda_\ell)\delta_0^{-\sigma_1}|k_\ell|^{\sigma_2-1}\|g_\ell\|_{X^{\sigma_1,\sigma_2}}\lesssim \varrho_{j}^2(y;\Lambda_\ell).
    \end{equation}
    Thus we have 
    \begin{equation}
        |g(y)|\lesssim|y-y_{j*}|^2,
    \end{equation}
    which gives \eqref{DeC12} by sending $\ell\to\infty$ in \eqref{DeC12.1} and no delta distribution is introduced at $y_{j*}$. Moreover, by \eqref{DeC12.2} and the Case II assumption, we have the limit function $g$ nontrivial. Thus, \eqref{DeC12} implies that $b(y_{j\ast})$ is an embedded eigenvalue for $L_k$, a contradiction to Assumption \ref{MaAs}. 

    {\it Subcase II.2:} If $(\sigma_1,\sigma_2) = (1,0)$, one needs to be careful about asserting $\kappa k_*\in\mathbb{Z}\backslash\{0\}$ since \eqref{DeC10.3}-\eqref{DeC10.3.1} no longer provide extra smallness as $\ell\to\infty$. If additionally,
    \begin{equation}
        \limsup_{\ell\to\infty}\left[\|\delta_\ell^{1/2}g_\ell\|_{L^2(S_{3\delta_\ell})}+\|\delta_\ell^{3/2}\partial_yg_\ell\|_{L^2(S_{3\delta_\ell})}\right]=0,
    \end{equation}
    then \eqref{DeC10.3}-\eqref{DeC10.3.1} still imply \eqref{DeC10.2}, which allows us to assert $\kappa k_*\in\mathbb{Z}\backslash\{0\}$ and follow the same arguments as in Subcase II.1 to obtain the contradiction.
    Otherwise, we have (passing to a subsequence if necessary)
    \begin{equation}
        \|\delta_\ell^{1/2}g_\ell\|_{L^2(S_{3\delta_\ell})}+\|\delta_\ell^{3/2}\partial_yg_\ell\|_{L^2(S_{3\delta_\ell})}\geq\sigma>0.
    \end{equation}
    One can still achieve the contradiction by following the blow-up arguments in Case I with $(\sigma_1,\sigma_2)=(1,0)$. A slight difference is that here Case I assumption no longer holds. Therefore, in the process of obtaining the global convergence of the limit function $H\in H^1(\mathbb{R})$, \eqref{DeC16.6} is obtained by $\|g_\ell\|_{L^\infty(\mathbb{T}\backslash S_{\delta_0})}\lesssim\|g_\ell\|_{X^{1,0}}$ and $\delta_\ell^{2+\sigma_1+\sigma_2}=\delta_\ell^3\to0$ as $\ell\to\infty$.


    
The proposition is now proved.

\label{ndint}
    Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma\backslash \cup_{j}\Sigma_{j, \delta_0}$, $\iota\in\{\pm\}, \epsilon \in (0, \epsilon_0)$, $\alpha\in\{0,1,2,\cdots\}$. The implicit constants may depend on $\alpha$.
    \begin{enumerate}
    \item For any function $f(y)\in L^2$, $\beta\in\{0,1\}$, we have the following estimates
                                     
                                                                                                                                                                                           
                    
    \begin{equation}\label{ndlogl2}
        |k|^{1-\beta}\left\|\int_{\mathbb{T}}\partial_y^{\beta} G_k(y,z)f(z)(\log(b(z)-\lambda+i\iota\epsilon))^\alpha dz\right\|_{L^2}\lesssim\frac{1}{|k|^{1/2}}\|f\|_{L^2}.
                                                                                       
    \end{equation}
                      
                                                                                                                                                                                           
                    
                      
                                                                                                                                                                                                                                                            
                    
    \item For any function $f(y)\in H^1_k$, we have the following estimates
                                      
                                                                                                                                                                                                                                             
                    
                                                 
    \begin{equation}\label{ndfracl2}
        \left\|\int_{\mathbb{T}}\partial_yG_k(y,z)f(z)\frac{(\log(b(z)-\lambda+i\iota\epsilon))^\alpha}{b(z)-\lambda+i\iota\epsilon}dz\right\|_{L^2}\lesssim\frac{1}{|k|^{1/2}}\|f\|_{H^1_k}.
    \end{equation}
    \end{enumerate}

\eqref{ndlogl2} follows from \eqref{Helm1.0}, H\"older's and Young's inequalities. In order to obtain \eqref{ndfracl2}, we use the integration by parts in the singular region
    \begin{equation}
        \begin{split}
            &\int_{\mathbb{T}}\partial_yG_k(y,z)(1-\chi_{\ast,\delta_0/10}(z))f(z)\frac{(\log(b(z)-\lambda+i\iota\epsilon))^\alpha}{b(z)-\lambda+i\iota\epsilon}dz\\
            =&\int_{\mathbb{T}}\partial_yG_k(y,z)(1-\chi_{\ast,\delta_0/10}(z))f(z)\frac{1}{b'(z)}\partial_z\left(\frac{1}{\alpha+1}(\log(b(z)-\lambda+i\iota\epsilon))^{\alpha+1}\right)dz\\
            =&-\int_{\mathbb{T}}\partial_z\left(\frac{\partial_yG_k(y,z)f(z)(1-\chi_{\ast,\delta_0/10}(z))}{(\alpha+1)b'(z)}\right)(\log(b(z)-\lambda+i\iota\epsilon))^{\alpha+1}dz\\
            =&-(1-\chi_{\ast,\delta_0/10}(y))\frac{f(y)}{(\alpha+1)b'(y)}(\log(b(y)-\lambda+i\iota\epsilon))^{\alpha+1}\\
            &-\int_{\mathbb{T}}\frac{F_k(y,z)f(z)(1-\chi_{\ast,\delta_0/10}(z))}{(\alpha+1)b'(z)}(\log(b(z)-\lambda+i\iota\epsilon))^{\alpha+1}dz\\
            &-\int_{\mathbb{T}}\partial_yG_k(y,z)\partial_z\left(\frac{(1-\chi_{\ast,\delta_0/10}(z))f(z)}{b'(z)}\right)\frac{1}{\alpha+1}(\log(b(z)-\lambda+i\iota\epsilon))^{\alpha+1}dz.
        \end{split}
    \end{equation}
    Together with \eqref{GkFk}
                                                   
    and the same routine as in obtaining \eqref{ndlogl2}, we have the following estimates for $\beta\in\{0,1\}$, $\alpha\in\{0,1,2,\cdots\}$:
                      
                                                                                                                                                                                                                                 
                    
          
    \begin{equation}\label{ndFlogl2}
        |k|^{-1-\beta}\left\|\int_{\mathbb{T}}\partial_y^\beta F_k(y,z)f(z)(\log(b(z)-\lambda+i\iota\epsilon))^\alpha dz\right\|_{L^2}\lesssim\frac{1}{|k|^{1/2}}\|f\|_{L^2}.
    \end{equation}
    \eqref{ndfracl2} then follows from \eqref{ndlogl2}, \eqref{ndFlogl2} and H\"older's inequality.

\label{ndraygeneral}
    Assume that $\kappa k\in\mathbb{Z}\backslash\{0\},\  y\in\mathbb{T},\  \lambda\in \Sigma\backslash \cup_{j}\Sigma_{j, \delta_0}$, $\iota\in\{\pm\}, \epsilon \in (0, \epsilon_0)$, $\alpha\in\{1,2,3\}$, and let $f(y,\lambda)$ satisfy
    \begin{equation}\label{ndrayf}
        \begin{split}
            &\left(-\partial_y^2+k^2+\frac{b''(y)}{b(y)-\lambda+i\iota\epsilon}\right)f(y,\lambda) \\
            &= c_1(y)\frac{\log(b(y)-\lambda+i\iota\epsilon)}{b(y)-\lambda+i\iota\epsilon}+c_2(y)\frac{1}{b(y)-\lambda+i\iota\epsilon}
            +c_{3}(y)(\log(b(y)-\lambda+i\iota\epsilon))^\alpha+c_4(y),
        \end{split}
    \end{equation}
                                        
    with coefficient functions $c_1(y), c_2(y)\in H^1_k$, and $c_{3}(y), c_{4}(y)\in L^2$. Then we have the following bounds for $f(y,\lambda)$:
    \begin{equation}\label{ndraygeneral1}
        \left\|f(\cdot,\lambda)\right\|_{H^1_k}\lesssim \frac{1}{|k|^{1/2}}\left(\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_{3}\|_{L^2}+\|c_{4}\|_{L^2}\right),
    \end{equation}
    and for any $1\leq p<2$,
    \begin{equation}\label{ndraygeneral2}
        \begin{split}
            \left\|\partial_y f(y,\lambda)-(1-\chi_{\ast,\delta_0\slash10}(y))\left(C_{1}(y)\left(\log(b(y)-\lambda+i\iota\epsilon)\right)^{2}+C_{2}(y)\log(b(y)-\lambda+i\iota\epsilon)\right)\right\|_{W^{1,p}}\\
        \lesssim_p \|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_{3}\|_{L^2}+\|c_{4}\|_{L^2},
        \end{split}
    \end{equation}
    with $\|(1-\chi_{\ast,\delta_0\slash10})C_1\|_{H^1_k}\lesssim\|c_1\|_{H^1_k}$, $\|(1-\chi_{\ast,\delta_0\slash10})C_2\|_{H^1_k}\lesssim\|c_2\|_{H^1_k}+|k|^{-1/2}\left(\|c_1\|_{H^1_k}+\|c_{3}\|_{L^2}+\right.$ $\left.\|c_{4}\|_{L^2}\right)$.

For convenience, we focus on the estimates on the highest derivatives as they are most singular. The lower order estimates follow similar calculations.
    We denote the right-hand side of \eqref{ndrayf} as $\mathcal{R}(y,\lambda)$. The integral form of \eqref{ndrayf} reads
    \begin{equation}\label{ndraygeneral3}
        f(y,\lambda)+ T_{\Theta}f(y,\lambda) = \int_{\mathbb{T}}G_k(y,z)\mathcal{R}(z,\lambda)dz.
    \end{equation}
    By the limiting absorption principle in Lemma \ref{T5}, in order to obtain \eqref{ndraygeneral1}, it suffices to prove that 
    \begin{equation}
        \begin{split}
            \left\|\int_{\mathbb{T}}G_k(y,z)\mathcal{R}(z,\lambda)dz\right\|_{H^1_k}
            \lesssim\frac{1}{|k|^{1/2}}\left(\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_{3}\|_{L^2}+\|c_{4}\|_{L^2}\right),
        \end{split}
    \end{equation}
    which follows directly from \eqref{ndlogl2} and \eqref{ndfracl2}.

    Moreover, \eqref{ndraygeneral3} gives
    \begin{equation}
        \begin{split}
            \partial_yf(y,\lambda) =& -\partial_y(T_{\Theta}f)(y,\lambda)+\partial_y\int_{\mathbb{T}}G_k(y,z)\mathcal{R}(z,\lambda)dz\\
            =&-\int_{\mathbb{T}}\partial_yG_k(y,z)\frac{b''(z)f(z,\lambda)}{b(z)-\lambda+i\iota\epsilon}dz+\int_{\mathbb{T}}\partial_yG_k(y,z)\mathcal{R}(z,\lambda)dz.\\
                                                                                                                                                                
                                                                                                                                                                                                
                                                                                                                                              
                                                                                                                                           
                                                                                                                          
        \end{split}
    \end{equation}
    Notice that since $\lambda\in \Sigma\backslash \cup_{j}\Sigma_{j, \delta_0}$, the denominator is uniformly bounded away from zero for $z\in \rm{supp}(\chi_{\ast,\delta_0\slash10})$. Therefore, 
    \begin{equation}\label{ndraygeneral3.1}
        \left\|\int_{\mathbb{T}}\partial_yG_k(y,z)\chi_{\ast,\delta_0\slash10}(z)\left(-\frac{b''(z)f(z,\lambda)}{b(z)-\lambda+i\iota\epsilon}+\mathcal{R}(z,\lambda)\right)dz\right\|_{H^1_k}\lesssim\|f\|_{L^2}+\sum_{i=1}^{4}\|c_i\|_{L^2},
    \end{equation}
    while in the remaining region, applying integration by parts gives
    \begin{equation}\label{ndraygeneral3.2}
        \begin{split}
            &\int_{\mathbb{T}}\partial_yG_k(y,z)(1-\chi_{\ast,\delta_0\slash10}(z))\left(-\frac{b''(z)f(z,\lambda)}{b(z)-\lambda+i\iota\epsilon}+\mathcal{R}(z,\lambda)\right)dz\\
            =&(1-\chi_{\ast,\delta_0\slash10}(y))\left(C_{1}(y)\left(\log(b(y)-\lambda+i\iota\epsilon)\right)^{2}+C_{2}(y)\log(b(y)-\lambda+i\iota\epsilon)\right)+r(y,\lambda),
        \end{split}
    \end{equation}
    where 
    \begin{align}
        C_1(y)=&-\frac{c_1(y)}{2b'(y)},\quad\ C_2(y) = \frac{b''(y)f(y,\lambda)-c_2(y)}{b'(y)},\\
        r(y,\lambda)=&-\int_{\mathbb{T}}F_k(y,z)(1-\chi_{\ast,\delta_0\slash10}(z))\frac{c_1(z)}{2b'(z)}\left(\log(b(z)-\lambda+i\iota\epsilon)\right)^2dz\notag\\
        &+\int_{\mathbb{T}}F_k(y,z)(1-\chi_{\ast,\delta_0\slash10}(z))\frac{b''(z)f(z,\lambda)-c_2(z)}{b'(z)}\log(b(z)-\lambda+i\iota\epsilon)dz\notag\\
        &+\int_{\mathbb{T}}\partial_yG_k(y,z)\partial_z\left((1-\chi_{\ast,\delta_0\slash10}(z))\frac{b''(z)f(z,\lambda)-c_2(z)}{b'(z)}\right)\log(b(z)-\lambda+i\iota\epsilon)dz\notag\\
        &-\int_{\mathbb{T}}\partial_yG_k(y,z)\partial_z\left(\frac{(1-\chi_{\ast,\delta_0\slash10}(z))c_1(z)}{2b'(z)}\right)\left(\log(b(z)-\lambda+i\iota\epsilon)\right)^2dz\notag\\
                                                                                                                                                                                         
        &+\int_{\mathbb{T}}\partial_yG_k(y,z)(1-\chi_{\ast,\delta_0\slash10}(z))c_3(z)(\log(b(z)-\lambda+i\iota\epsilon))^\alpha dz\notag\\
        &+\int_{\mathbb{T}}\partial_yG_k(y,z)(1-\chi_{\ast,\delta_0\slash10}(z))c_4(z)dz.\label{ndraygeneral3.3}
    \end{align}

    It is clear $\|(1-\chi_{\ast,\delta_0\slash10})C_1\|_{H^1_k}\lesssim\|c_1\|_{H^1_k}$, $\|(1-\chi_{\ast,\delta_0\slash10})C_2\|_{H^1_k}\lesssim\|c_2\|_{H^1_k}+|k|^{-1/2}\left(\|c_1\|_{H^1_k}+\right.$ $\left.\|c_{3}\|_{L^2}+\|c_{4}\|_{L^2}\right)$. The remainder term $r(y,\lambda)$ has higher regularity:
                               
                          
                           
                                                                                                                                                                                                
                                                                                                                                                                  
                                                                         
                         
                        
       
    \begin{align}\label{ndraygeneral4}
            \|\partial_yr(y,\lambda)\|_{L^p}&\lesssim\left\|\int_{\mathbb{T}}\partial_yF_k(y,z)(1-\chi_{\ast,\delta_0\slash10})(z)\frac{b''(z)f(z,\lambda)-c_2(z)}{b'(z)}\log(b(z)-\lambda+i\iota\epsilon)dz\right\|_{L^p}\notag\\
            &\quad+\left\|\int_{\mathbb{T}}-\partial_yF_k(y,z)(1-\chi_{\ast,\delta_0\slash10})(z)\frac{c_1(z)}{2b'(z)}\left(\log(b(z)-\lambda+i\iota\epsilon)\right)^2dz\right\|_{L^p}\notag\\
            &\quad+\left\|\partial_y\left((1-\chi_{\ast,\delta_0\slash10})(y)\frac{b''(y)f(y,\lambda)-c_2(y)}{b'(y)}\right)\log(b(y)-\lambda+i\iota\epsilon)\right\|_{L^p}\\
            &\quad+\left\|\partial_y\left(\frac{(1-\chi_{\ast,\delta_0\slash10})(y)c_1(y)}{2b'(y)}\right)\left(\log(b(y)-\lambda+i\iota\epsilon)\right)^2\right\|_{L^p}\notag\\
                                                                                                                                                                                                                                                                           
            &\quad+\left\|(1-\chi_{\ast,\delta_0\slash10})(y)c_3(y)(\log(b(y)-\lambda+i\iota\epsilon))^\alpha \right\|_{L^p}+\left\|(1-\chi_{\ast,\delta_0\slash10})(y)c_4(y)\right\|_{L^p}\notag\\
            &\lesssim_p\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_3\|_{L^2}+\|c_4\|_{L^2}.
    \end{align}
    The conclusion follows from \eqref{ndraygeneral3.1}, \eqref{ndraygeneral3.2}, \eqref{ndraygeneral3.3} and \eqref{ndraygeneral4}.

\label{ndrayg}
    Suppose that $f(y,\lambda)\in H^1_k$ is the solution of \eqref{ndrayf} as in Lemma \ref{ndraygeneral}. For any $g(y,\lambda)$, $y\in\mathbb{T}$ satisfying 
    \begin{equation}
        \left(-\partial_y^2+k^2+\frac{b''(y)}{b(y)-\lambda+i\iota\epsilon}\right)g(y,\lambda)=\mathfrak{c}(y)\frac{\partial_y f(y,\lambda)}{b(y)-\lambda+i\iota\epsilon},\quad\ \|\mathfrak{c}(y)\|_{C^1}\lesssim1,
    \end{equation}
    we have 
    \begin{equation}\label{ndrayg1}
        \|g(\cdot,\lambda)\|_{H^1_k}\lesssim\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_3\|_{L^2}+\|c_4\|_{L^2}.
    \end{equation}

By the limiting absorption principle, it suffices to prove 
    \begin{equation}\label{ndrayg2}
        \left\|\int_{\mathbb{T}}G_k(y,z)\frac{\mathfrak{c}(z)\partial_zf(z,\lambda)}{b(z)-\lambda+i\iota\epsilon}dz\right\|_{H^1_k}\lesssim\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_3\|_{L^2}+\|c_4\|_{L^2}.
    \end{equation}
    In fact, in the singular region
    \begin{equation}\label{ndintpsi_y1}
    \begin{split}
        &\int_{\mathbb{T}}\partial_yG_k(y,z)\frac{(1-\chi_{\ast,\delta_0\slash10}(z))\mathfrak{c}(z)\partial_z f(z,\lambda)}{b(z)-\lambda+i\iota\epsilon}dz\\
        =&-\int_{\mathbb{T}}\partial_z\left(\frac{\partial_yG_k(y,z)(1-\chi_{\ast,\delta_0\slash10}(z))\mathfrak{c}(z)\partial_zf(z,\lambda)}{b'(z)}\right)\log(b(z)-\lambda+i\iota\epsilon)dz\\
        =&-(1-\chi_{\ast,\delta_0\slash10}(y))\frac{\mathfrak{c}(y)\partial_yf(y)}{b'(y)}\log(b(y)-\lambda+i\iota\epsilon)\\
        &-\int_{\mathbb{T}}\frac{F_k(y,z)(1-\chi_{\ast,\delta_0\slash10}(z))\mathfrak{c}(z)\partial_zf(z,\lambda)}{b'(z)}\log(b(z)-\lambda+i\iota\epsilon)dz\\
        &-\int_{\mathbb{T}}\partial_yG_k(y,z)\partial_zf(z,\lambda)\partial_z\left((1-\chi_{\ast,\delta_0\slash10}(z))\frac{\mathfrak{c}(z)}{b'(z)}\right)\log(b(z)-\lambda+i\iota\epsilon)dz\\
        &-\int_{\mathbb{T}}(1-\chi_{\ast,\delta_0\slash10}(z))\frac{\partial_yG_k(y,z)\mathfrak{c}(z)\partial_z^2f}{b'(z)}\log(b(z)-\lambda+i\iota\epsilon)dz.
    \end{split}
\end{equation}
                          
{\color{black}
In the following equation, $r$ includes the regular-region integral in
\eqref{ndraygeneral3.1} in addition to the remainder in
\eqref{ndraygeneral3.3}.
\par}
                        

By Lemma \ref{ndraygeneral}, the first term, which is the most singular among all, has the $L^2$ bound
\begin{equation}
    \begin{split}
        &\left\|(1-\chi_{\ast,\delta_0\slash10}(y))\frac{\mathfrak{c}(y)\partial_yf}{b'(y)}\log(b(y)-\lambda+i\iota\epsilon)\right\|_{L^2}\\
        \lesssim&\|(1-\chi_{\ast,\delta_0\slash10}(y))\bigl[C_{1}(y)\left(\log(b(y)-\lambda+i\iota\epsilon)\right)^{3}+C_{2}(y)(\log(b(y)-\lambda+i\iota\epsilon))^2\bigr]\|_{L^2}\\
        &+\|r(y,\lambda)\log(b(y)-\lambda+i\iota\epsilon)\|_{L^2}\\
\lesssim&\|(1-\chi_{\ast,\delta_0\slash10})C_1\|_{H^1_k}+\|(1-\chi_{\ast,\delta_0\slash10})C_2\|_{H^1_k}+\|r\|_{W^{1,p}}\\
\lesssim&\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_3\|_{L^2}+\|c_4\|_{L^2}.
    \end{split}
\end{equation}
The second and third terms follow from \eqref{ndlogl2} and \eqref{ndraygeneral2}. The only term requiring extra care is the last one. By \eqref{ndrayf}, we have $\partial_z^2f=k^2f+\frac{b''(z)f}{b(z)-\lambda+i\iota\epsilon}-\mathcal{R}$. Together with \eqref{ndlogl2}, \eqref{ndfracl2} and \eqref{ndraygeneral1}, we obtain
\begin{align}\label{ndintpsi_y2}
        &\left\|\int_{\mathbb{T}}(1-\chi_{\ast,\delta_0\slash10}(z))\frac{\partial_yG_k(y,z)\mathfrak{c}(z)\partial_z^2f}{b'(z)}\log(b(z)-\lambda+i\iota\epsilon)dz\right\|_{L^2}\notag\\
        \lesssim&\left\|\int_{\mathbb{T}}\partial_yG_k(y,z)(1-\chi_{\ast,\delta_0\slash10}(z))\frac{\mathfrak{c}(z)c_1(z)}{b'(z)}\frac{(\log(b(z)-\lambda+i\iota\epsilon))^2}{b(z)-\lambda+i\iota\epsilon}dz\right\|_{L^2}\notag\\
        &+\left\|\int_{\mathbb{T}}\partial_yG_k(y,z)(1-\chi_{\ast,\delta_0\slash10}(z))\frac{\mathfrak{c}(z)}{b'(z)}\left(b''(z)f(z)-c_2(z)\right)\frac{\log(b(z)-\lambda+i\iota\epsilon)}{b(z)-\lambda+i\iota\epsilon}dz\right\|_{L^2}\notag\\
        &+\left\|\int_{\mathbb{T}}-\partial_yG_k(y,z)(1-\chi_{\ast,\delta_0\slash10}(z))\frac{\mathfrak{c}(z)c_3(z)}{b'(z)}(\log(b(z)-\lambda+i\iota\epsilon))^{\alpha+1}dz\right\|_{L^2}\notag\\
        &+\left\|\int_{\mathbb{T}}\partial_yG_k(y,z)(1-\chi_{\ast,\delta_0\slash10}(z))\frac{\mathfrak{c}(z)}{b'(z)}(-c_4(z)+k^2f(z))\log(b(z)-\lambda+i\iota\epsilon)dz\right\|_{L^2} \notag\\
        \lesssim&\frac{1}{|k|^{1/2}}\left(\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+|k|\|f\|_{H^1_k}+\|c_3\|_{L^2}+\|c_{4}\|_{L^2}\right)\notag\\
        \lesssim&\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_{3}\|_{L^2}+\|c_{4}\|_{L^2}.
                                                                                                                                                                                           
                                                                                                                                           
                                                                                                                                                                          
\end{align}
                                                  
Thus we proved \eqref{ndrayg2}.

\label{ndpsi}
    Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma\backslash \cup_{j}\Sigma_{j, \delta_0}$ and let $\psi_{k,\epsilon}^{\iota}(y,\lambda)$ with $\iota\in\{\pm\}, \epsilon \in (0, \epsilon_0)$ be as defined in \eqref{F7}. 
    Then we have the bound
    \begin{equation}
        \begin{split}
            \norm{\psi }_{H^1_{k}} \lesssim \frac{\big\|\omega_{0k}\big\|_{H^1_k}}{|k|^{1/2}}.
        \end{split}
    \end{equation}
    Moreover, for any $1\leq p<2$,
    \begin{equation}\label{ndpsi_y}
        \left\|\partial_y\psi_{k,\epsilon}^{\iota}(y,\lambda)-C(y)(1-\chi_{\ast,\delta_0\slash10}(y))\log(b(y)-\lambda+i\iota\epsilon)\right\|_{W^{1,p}}\lesssim\|\omega_{0k}\|_{H^1_k},
    \end{equation}
    with $\left\|C(y)\right\|_{H^1_k}\lesssim\|\omega_{0k}\|_{H^1_k}$.

\label{ndpsi_l}
    Assume that $ \kappa k\in\mathbb{Z}\backslash\{0\},\, \lambda\in \Sigma\backslash \cup_{j}\Sigma_{j, \delta_0},\, \epsilon \in (0, \epsilon_0),\,  \iota\in\{\pm\}$.
    Let $\psi_{k,\epsilon}^{\iota}(y,\lambda)$ be as defined in \eqref{F7}.
    Denote for $y\in \mathbb{T} $,
    \begin{equation}
        \begin{split}
            &\mathcal{S}^\iota_{1,0,\epsilon}(y,\lambda):=\, -(1-\chi_{\ast,\delta_0\slash10}(y))(b''(y) \psi(y, \lambda)-\omega_{0k}(y)) \frac{1}{(b'(y))^2}\log(b(y)-\lambda+i\iota\epsilon).\\
                                                                                                                     
        \end{split}
    \end{equation}
    We have the bounds 
    \begin{equation}\label{ndpsi_l1}
        \norm{  \partial_\lambda \psi_{k, \epsilon}^\iota  - \mathcal{S}^\iota_{1,0,\epsilon} }_{H^1_k} \lesssim \frac{\big\|\omega_{0k}\big\|_{H^2_k}}{|k|^{1/2}}.
    \end{equation}

By the Rayleigh equation, $\partial_\lambda\psi_{k,\epsilon}^{\iota}(y,\lambda)-\mathcal{S}^\iota_{1,0,\epsilon}$ satisfies
    \begin{equation}
        \left(\partial_y^2-k^2-\frac{b''(y)}{b(y)-\lambda+i\iota\epsilon}\right)\left(\partial_\lambda\psi_{k,\epsilon}^{\iota}(y,\lambda)-\mathcal{S}^\iota_{1,0,\epsilon}\right)=\mathcal{R}^\iota_{1,0,\epsilon}(y,\lambda),
    \end{equation}
    where $\mathcal{R}^\iota_{1,0,\epsilon}$ is explicit by a direct computation.
    By the previous Lemmas, one can simplify it to the form
                      
                       
                                                                                                                                                                                           
                                      
                                                                                                                                         
                                                                                                                                       
                                                                              
                                      
                                                                                     
                                                                                                                                                           
                                                                                                                                                     
                                                                      
                                                
                                                             
                     
                
                               
                                                                                                                                                                            
\begin{equation}
    \mathcal{R}^\iota_{1,0,\epsilon}(y,\lambda) = c_1(y)\frac{\log(b(y)-\lambda+i\iota\epsilon)}{b(y)-\lambda+i\iota\epsilon}+\frac{c_2(y)+\mathfrak{c}(y)\partial_y\psi}{b(y)-\lambda+i\iota\epsilon}+c_{3}(y)\log(b(y)-\lambda+i\iota\epsilon)+c_4(y),
\end{equation}
with $|k|\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_{3}\|_{L^2}+\|c_{4}\|_{L^2}\lesssim\|\omega_{0k}\|_{H^2_k}$. Therefore, \eqref{ndpsi_l1} follows from Lemmas \ref{ndraygeneral}, \ref{ndrayg} directly.

\label{ndpsi_D}
Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma\backslash \cup_{j}\Sigma_{j, \delta_0}$ and let $\psi_{k,\epsilon}^{\iota}(y,\lambda)$ with $\iota\in\{\pm\}, \epsilon \in (0, \epsilon_0)$ be as defined in \eqref{F7}. 
Then we have the bound 
    \begin{equation}
        \begin{split}
            \norm{ D_\lambda \psi_{k, \epsilon}^\iota }_{H^1_k} \lesssim \frac{\big\|\omega_{0k}\big\|_{H^2_k}}{|k|^{1/2}}.
        \end{split}
    \end{equation}
And, for any $1\leq p<2$,
    \begin{equation}
        \left\|\partial_yD_\lambda\psi_{k,\epsilon}^{\iota}(y,\lambda) -C(y)(1-\chi_{\ast,\delta_0\slash10}(y))\log(b(y)-\lambda+i\iota\epsilon)\right\|_{W^{1,p}}\lesssim \|\omega_{0k}\|_{H^2_k},
    \end{equation}
    with $\|C(y)\|_{H^1_k}\lesssim\|\omega_{0k}\|_{H^2_k}$.

Using the Rayleigh equation together with Lemmas \ref{ndpsi} and \ref{ndpsi_l}, we obtain 
                
                 
                        
                                                                                                                                                            
                                                                                                       
                                                                                                                                                                                                
                      
       
    \begin{equation}\label{Raypsi_D}
        \begin{split}
            &\left(\partial_y^2-k^2-\frac{b''(y)}{b(y)-\lambda+i\iota\epsilon}\right)D_\lambda\psi_{k,\epsilon}^{\iota}(y,\lambda) \\
            &= \frac{b'''(y)\psi(y,\lambda)-\omega_{0k}'(y)}{b(y)-\lambda+i\iota\epsilon}+b'''(y)\partial_\lambda\psi(y,\lambda)+2b''(y)\partial_y\partial_\lambda\psi(y,\lambda)\\
            &=\frac{c_2(y)}{b(y)-\lambda+i\iota\epsilon}+c_3(y)\log(b(y)-\lambda+i\iota\epsilon)+c_4(y).
        \end{split}
    \end{equation}
    Here $\|c_2\|_{H^1_k}+\|c_3\|_{L^2}+\|c_4\|_{L^2}\lesssim\|\omega_{0k}\|_{H^2_k}$.
    The conclusion follows from Lemma \ref{ndraygeneral}.

\label{ndpsi_l2}
    Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma\backslash \cup_{j}\Sigma_{j, \delta_0},\, \epsilon \in (0, \epsilon_0),\, \iota\in\{\pm\}$, and let $\psi_{k,\epsilon}^{\iota}(y,\lambda)$ be as defined in \eqref{F7}. 
    For $y\in \mathbb{T}$, set
    \begin{equation}\label{ndS20}
        \begin{split}
            \mathcal{S}_{2, 0, \epsilon}^\iota(y, \lambda) &:=   C_1(1-\chi_{\ast,\delta_0\slash10}(y))\frac{b''(y)\psi(y,\lambda)-\omega_{0k}(y)}{b(y)-\lambda+i\iota\epsilon}\\
            &+\left[C_2(y)D_\lambda\psi(y,\lambda)+C_3(y)\psi(y,\lambda)+\Omega_{0k}(y)  \right](1-\chi_{\ast,\delta_0\slash10}(y))\log(b(y)-\lambda+i\iota\epsilon),
        \end{split}
    \end{equation}
    where 
    \begin{equation}
        \begin{split}
            &\Omega_{0k}(y)=C_4(y)\omega_{0k}'(y)+C_5(y)\omega_{0k}(y),\\
            &C_1(y)=\frac{1}{(b'(y))^2},\quad\ C_2(y)=-\frac{2b''(y)}{(b'(y))^3},\quad\ C_3(y)=-\frac{2b'''(y)}{(b'(y))^3}+\frac{3(b''(y))^2}{(b'(y))^4},\\
            &C_4(y)=\frac{2}{(b'(y))^3},\quad\ C_5(y)=-\frac{3b''(y)}{(b'(y))^4}.
        \end{split}
    \end{equation}
    Then we have the bounds
    \begin{equation}
        \norm{\partial_\lambda^2 \psi_{k, \epsilon}^\iota   - \mathcal{S}_{2, 0, \epsilon}^\iota }_{H^1_k} \lesssim  \frac{\big\|\omega_{0k}\big\|_{H^3_k}}{|k|^{1/2}}.
    \end{equation}

The Rayleigh equation for $\partial_\lambda^2\psi_{k,\epsilon}^{\iota}(y,\lambda)-\mathcal{S}_{2, 0, \epsilon}^\iota$ can be written as
    \begin{equation}
        \left(\partial_y^2-k^2-\frac{b''(y)}{b(y)-\lambda+i\iota\epsilon}\right)\left(\partial_\lambda^2\psi_{k,\epsilon}^{\iota}(y,\lambda)-\mathcal{S}_{2, 0, \epsilon}^\iota\right)=\mathcal{R}^\iota_{2,0,\epsilon}(y,\lambda).
    \end{equation}
                                                                                                              
                      
                       
                                                                                                                                                                                               
                                                                                                                               
                                                                                                                                                                                    
                                                                                                                                                                            
                                                        
                                                
                                                             
                     
                    
    Similar to the proof of Lemma \ref{ndpsi_l}, one can reorganize 
    \begin{equation}
        \begin{split}
            \mathcal{R}^\iota_{2,0,\epsilon}(y,\lambda)=&c_1(y)\frac{\log(b(y)-\lambda+i\iota\epsilon)}{b(y)-\lambda+i\iota\epsilon}+\frac{c_2(y)+\mathfrak{c}_1(y)\partial_yD_\lambda\psi+\mathfrak{c}_2(y)\partial_y\psi}{b(y)-\lambda+i\iota\epsilon}\\
            &+c_3(y)\log(b(y)-\lambda+i\iota\epsilon)+c_4(y).
        \end{split}
    \end{equation}
    Here $k^2\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_3\|_{L^2}+\|c_{4}\|_{L^2}\lesssim\|\omega_{0k}\|_{H^3_k}$. The conclusion follows directly from Lemmas \ref{ndraygeneral}, \ref{ndrayg}.

\label{ndpsi_lD}
   Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma\backslash \cup_{j}\Sigma_{j, \delta_0},\, \epsilon \in (0, \epsilon_0),\, \iota\in\{\pm\}$, and let $\psi_{k,\epsilon}^{\iota}(y,\lambda)$ be as defined in \eqref{F7}. 
    For $y\in \mathbb{T}$, set
    \begin{equation}
        \mathcal{S}_{1,1,\epsilon}^\iota(y,\lambda): =\big(C_1(y)D_\lambda\psi+C_2(y)\psi(y)+\Omega_{0k}(y)\big)(1-\chi_{\ast,\delta_0\slash10}(y))\log(b(y)-\lambda+i\iota\epsilon), 
    \end{equation}
    where 
    \begin{equation}
        \begin{split}
            &\Omega_{0k}(y)=C_3\omega_{0k}'(y)+C_4(y)\omega_{0k}(y),\\
            &C_1(y)=-\frac{b''}{(b')^2},\quad\ C_2(y)=-\frac{b'''}{(b')^2}+\frac{2(b'')^2}{(b')^3},\quad\ C_3(y)=\frac{1}{(b')^2},\quad\ C_4(y)=-\frac{2b''}{(b')^3}.
        \end{split}
    \end{equation}
    Then we have the bounds 
    \begin{equation}
        \|\partial_\lambda D_\lambda\psi_{k,\epsilon}^{\iota}-\mathcal{S}_{1,1,\epsilon}^\iota\|_{H^1_k}\lesssim\frac{\big\|\omega_{0k}\big\|_{H^3_k}}{|k|^{1/2}}.
    \end{equation}

Notice that by \eqref{ndS20}, one can rewrite $\mathcal{S}_{1,1,\epsilon}^{\iota}$ as follows.
    \begin{equation}
        \begin{aligned}
        \mathcal{S}_{1,1,\epsilon}^{\iota}={}&b'\left(\partial_\lambda^2\psi-r_{2,0,\epsilon}^\iota\right)
        +\left(-\frac{b''}{b'}\psi+\frac{\omega_{0k}}{b'}\right)
        \frac{1-\chi_{\ast,\delta_0\slash10}(y)}{b-\lambda+i\iota\epsilon}\\
&+\left\{\begin{aligned}
&-\frac{\omega_{0k}'}{(b')^2}
+\left[\frac{b'''}{(b')^2}-\frac{(b'')^2}{(b')^3}\right]\psi\\
&+\frac{b''}{(b')^3}\omega_{0k}+\frac{b''}{(b')^2}D_\lambda\psi
\end{aligned}\right\}
(1-\chi_{\ast,\delta_0\slash10}(y))\log(b-\lambda+i\iota\epsilon).
        \end{aligned}
    \end{equation}
    Here we take $r_{2,0,\epsilon}^\iota(y,\lambda):=\partial_\lambda^2 \psi_{k, \epsilon}^\iota   - \mathcal{S}_{2, 0, \epsilon}^\iota$. By Lemma \ref{ndpsi_l2}, $\|r_{2,0,\epsilon}^\iota\|_{H^1_k} \lesssim  |k|^{-1/2}\|\omega_{0k}\|_{H^3_k}$.
    Then $\partial_\lambda D_\lambda\psi_{k,\epsilon}^{\iota}-\mathcal{S}_{1,1,\epsilon}^\iota$ satisfies
    \begin{equation}
        \left(\partial_y^2-k^2-\frac{b''(y)}{b(y)-\lambda+i\iota\epsilon}\right)\left(\partial_\lambda D_\lambda\psi_{k,\epsilon}^{\iota}-\mathcal{S}_{1,1,\epsilon}^\iota\right)=\mathcal{R}^\iota_{1,1,\epsilon}.
    \end{equation}
                      
                       
                                                                                                                                                                                          
                                                                                                                
                                                                                                                                                                        
                                                                                                                                                                            
                                                        
                                                
                                                             
                     
                    
                                                                                                               
    Here $\mathcal{R}^\iota_{1,1,\epsilon}$ can be reorganized as 
    \begin{equation}
        \begin{split}
            \mathcal{R}^\iota_{1,1,\epsilon}=&c_1(y)\frac{\log(b(y)-\lambda+i\iota\epsilon)}{b(y)-\lambda+i\iota\epsilon}+\frac{c_2(y)+\mathfrak{c}_1(y)\partial_yD_\lambda\psi+\mathfrak{c}_2(y)\partial_y\psi}{b(y)-\lambda+i\iota\epsilon}\\
            &+c_{3}(y)\log(b(y)-\lambda+i\iota\epsilon)+c_4(y),
        \end{split}
    \end{equation}
    with  $k^2\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_{3}\|_{L^2}+\|c_{4}\|_{L^2}\lesssim\|\omega_{0k}\|_{H^3_k}$. Therefore, our conclusion follows from Lemmas \ref{ndraygeneral}, \ref{ndrayg} directly.

Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma\backslash \cup_{j}\Sigma_{j, \delta_0},\, \epsilon \in (0, \epsilon_0),\, \iota\in\{\pm\}$, and let $\psi_{k,\epsilon}^{\iota}(y,\lambda)$ be as defined in \eqref{F7}. 
    Then we have the bound 
    \begin{equation}\label{ndD2:bdd}
        \|D_\lambda^2\psi_{k,\epsilon}^{\iota}\|_{H^1_k}\lesssim\frac{\big\|\omega_{0k}\big\|_{H^3_k}}{|k|^{1/2}}.
    \end{equation}
    In addition, for any $1\leq p<2$,
    \begin{equation}
        \left\|\partial_yD_\lambda^2\psi_{k,\epsilon}^{\iota}(y,\lambda)-C(y)(1-\chi_{\ast,\delta_0\slash10}(y))\log(b(y)-\lambda+i\iota\epsilon)\right\|_{W^{1,p}}\lesssim\|\omega_{0k}\|_{H^3_k},
    \end{equation}
    with $\|C\|_{H^1_k}\lesssim\|\omega_{0k}\|_{H^3_k}$.

We argue as in the proof of Lemma \ref{ndpsi_D}. According to the Rayleigh equation together with Lemmas \ref{ndpsi}-\ref{ndpsi_lD}, we have 
    \begin{equation}\label{ndRayD2psi}
        \begin{split}
        &\left(\partial_y^2-k^2-
        \frac{b''}{b-\lambda+i\iota\epsilon}\right)D_\lambda^2\psi\\
        =&\frac{b^{(4)}\psi+2b'''D_\lambda\psi-\omega_{0k}''}{b-\lambda+i\iota\epsilon}+4b''\partial_y\partial_\lambda D_\lambda\psi
        +2b'''\partial_\lambda D_\lambda\psi-2(b'')^2\partial_\lambda^2\psi+2b'''\partial_y\partial_\lambda\psi+b^{(4)}\partial_\lambda\psi\\
        =&\frac{c_2(y)}{b(y)-\lambda+i\iota\epsilon}+c_{3,1}(y)\log(b(y)-\lambda+i\iota\epsilon)+c_{3,2}(y)(\log(b(y)-\lambda+i\iota\epsilon))^2+c_4(y).
        \end{split}
    \end{equation}
    Here $\|c_2\|_{H^1_k}+\|c_{3,1}\|_{L^2}+\|c_{3,2}\|_{L^2}+\|c_{4}\|_{L^2}\lesssim \|\omega_{0k}\|_{H^3_k}$. The conclusion follows directly from Lemma \ref{ndraygeneral}.

\label{ndpsi_l3}
    Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma\backslash \cup_{j}\Sigma_{j, \delta_0},\, \epsilon \in (0, \epsilon_0),\, \iota\in\{\pm\}$, and let $\psi_{k,\epsilon}^{\iota}(y,\lambda)$ be as defined in \eqref{F7}. 
    For $y\in \mathbb{T}$, set
    \begin{equation}
        \begin{split}
            \mathcal{S}_{3, 0,\epsilon}^\iota(y, \lambda) &:=   C_1(1-\chi_{\ast,\delta_0\slash10}(y))\frac{b''(y)\psi(y,\lambda)-\omega_{0k}(y)}{(b(y)-\lambda+i\iota\epsilon)^2}\\
&+\left[\begin{aligned}
&C_2(y)\partial_y\psi(y,\lambda)+C_3(y)D_\lambda\psi(y,\lambda)\\
&+C_4(y)\psi(y,\lambda)+\Omega_{0k,1}(y)
\end{aligned}\right]\frac{1-\chi_{\ast,\delta_0\slash10}(y)}{b(y)-\lambda+i\iota\epsilon}\\
            &+\left[\begin{aligned}
&C_7(y)D_\lambda^2\psi+C_8(y)D_\lambda\psi\\
&+C_9\psi(y,\lambda)+\Omega_{0k,2}(y)
\end{aligned}\right](1-\chi_{\ast,\delta_0\slash10}(y))\log(b(y)-\lambda+i\iota\epsilon),
        \end{split}
    \end{equation}
    where 
    \begin{equation}
        \begin{split}
            &\Omega_{0k,1} = C_5(y)\omega_{0k}'(y)+C_6(y)\omega_{0k}(y),\quad\ \Omega_{0k,2} = C_{10}(y)\omega_{0k}''(y)+C_{11}(y)\omega_{0k}'(y)+C_{12}(y)\omega_{0k}(y),\\
            &C_1(y)=\frac{1}{(b'(y))^2},\quad\ C_2(y)=-\frac{b''}{(b')^3},\quad\ C_3(y)=\frac{3b''}{(b')^3},\\
            &C_4(y)=\frac{2b'''}{(b')^3}-\frac{3(b'')^2}{(b')^4},\quad\ C_5(y)=-\frac{2}{(b')^3},\quad\ C_6(y) =\frac{3b''}{(b')^4}, \\
            &C_7(y)=-\frac{3b''}{(b')^4},\quad\ C_8(y) =-\frac{6b'''}{(b')^4}+\frac{12(b'')^2}{(b')^5},\\
            &C_{9}(y)=-\frac{3b^{(4)}}{(b')^4}+\frac{16b''b'''}{(b')^5}-\frac{15(b'')^3}{(b')^6}-\frac{k^2b''}{(b')^4},\quad\ C_{10}(y)=\frac{3}{(b')^4},\\
            &C_{11}(y)=-\frac{12b''}{(b')^5},\quad\ C_{12}(y) =\frac{k^2}{(b')^4}-\frac{4b'''}{(b')^5}+\frac{15(b'')^2}{(b')^6}.
        \end{split}
    \end{equation}
    Then we have the bounds
    \begin{equation}
        \norm{\partial_\lambda^3 \psi_{k, \epsilon}^\iota   - \mathcal{S}_{3, 0,\epsilon}^\iota }_{H^1_k} \lesssim  \frac{\big\|\omega_{0k}\big\|_{H^4_k}}{|k|^{1/2}}.
    \end{equation}

The Rayleigh equation for $\partial_\lambda^3\psi_{k,\epsilon}^{\iota}(y,\lambda)-\mathcal{S}^\iota_{3,0,\epsilon}$ is 
    \begin{equation}
        \left(\partial_y^2-k^2-\frac{b''(y)}{b(y)-\lambda+i\iota\epsilon}\right)\left(\partial_\lambda^3\psi_{k,\epsilon}^{\iota}(y,\lambda)-\mathcal{S}^\iota_{3,0,\epsilon}\right)=\mathcal{R}^\iota_{3,0,\epsilon}(y,\lambda).
    \end{equation}
                      
                   
                                                                                                                                                                                           
                                                                                                                                                                    
                                     
                                                                                                                                          
                                                                              
                                                                         
                                     
                                                                                                                                 
                                                                                                  
                                                                              
                                                                     
                                                
                                                             
                 
                
                                                                                                           
Here $\mathcal{R}^\iota_{3,0,\epsilon}$ can be simplified by 
\begin{equation}
    \begin{split}
        \mathcal{R}^\iota_{3,0,\epsilon}(y,\lambda)=&c_1(y)\frac{\log(b(y)-\lambda+i\iota\epsilon)}{b(y)-\lambda+i\iota\epsilon}+\frac{c_2(y)+\mathfrak{c}_1(y)\partial_yD_\lambda^2\psi+\mathfrak{c}_2(y)\partial_yD_\lambda\psi+\mathfrak{c}_3(y)\partial_y\psi}{b(y)-\lambda+i\iota\epsilon}\\
        &+c_3(y)\log(b(y)-\lambda+i\iota\epsilon)+c_4(y),
    \end{split}
\end{equation}
with $k^2\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_3\|_{L^2}+\|c_{4}\|_{L^2}\lesssim\|\omega_{0k}\|_{H^4_k}$. The conclusion follows directly from Lemmas \ref{ndraygeneral}, \ref{ndrayg}.

\label{ndpsi_l2D}
    Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma\backslash \cup_{j}\Sigma_{j, \delta_0},\, \epsilon \in (0, \epsilon_0),\, \iota\in\{\pm\}$, and let $\psi_{k,\epsilon}^{\iota}(y,\lambda)$ be as defined in \eqref{F7}. 
    For $y\in \mathbb{T}$, set
                                                                                                                              
\begin{equation}\label{ndS21}
        \begin{split}
            \mathcal{S}_{2, 1, \epsilon}^\iota(y, \lambda) &:= \left[C_1(y)D_\lambda\psi(y,\lambda)+C_2(y)\psi(y,\lambda)+\Omega_{0k,1}(y)\right]\frac{1-\chi_{\ast,\delta_0\slash10}(y)}{b(y)-\lambda+i\iota\epsilon}\\
            &+\left[
                \begin{aligned}
                    &C_5(y)D_\lambda^2\psi(y,\lambda)+C_6(y)D_\lambda\psi(y,\lambda)\\
                    &+C_7(y)\psi(y,\lambda)+\Omega_{0k,2}(y)
                \end{aligned}    
            \right](1-\chi_{\ast,\delta_0\slash10}(y))\log(b(y)-\lambda+i\iota\epsilon),
        \end{split}
    \end{equation}
    where 
    \begin{equation}
        \begin{split}
&\Omega_{0k,1}(y)=C_3(y)\omega_{0k}'(y)+C_4(y)\omega_{0k}(y),\\
&\Omega_{0k,2}(y)=C_8(y)\omega_{0k}''(y)+C_9(y)\omega_{0k}'(y)+C_{10}(y)\omega_{0k}(y),\\
            &C_1(y)=\frac{b''}{(b')^2},\quad\ C_2(y)=\frac{b'''}{(b')^2}-\frac{2(b'')^2}{(b')^3},\quad\ C_3(y)=-\frac{1}{(b')^2},\quad\ C_4(y)=\frac{2b''}{(b')^3},\\
            &C_5(y)=-\frac{2b''}{(b')^3},\quad\ C_6(y)=-\frac{4b'''}{(b')^3}+\frac{9(b'')^2}{(b')^4},\quad\ C_7(y)=-\frac{2b^{(4)}}{(b')^3}+\frac{12b''b'''}{(b')^4}-\frac{12(b'')^3}{(b')^5},\\
            &C_8(y)=\frac{2}{(b')^3},\quad\ C_9(y)=-\frac{9b''}{(b')^4},\quad\ C_{10}(y)=-\frac{3b'''}{(b')^4}+\frac{12(b'')^2}{(b')^5}.
        \end{split}
    \end{equation}
    Then we have the bounds
    \begin{equation}
        \norm{\partial_\lambda^2 D_\lambda \psi_{k, \epsilon}^\iota   - \mathcal{S}_{2, 1, \epsilon}^\iota }_{H^1_k} \lesssim  \frac{\big\|\omega_{0k}\big\|_{H^4_k}}{|k|^{1/2}}.
    \end{equation}

Similar to the arguments in Lemma \ref{ndpsi_lD}, one can rewrite $\mathcal{S}_{2,1, \epsilon}^\iota$ as follows
    \begin{equation}
        \begin{split}
            \mathcal{S}_{2,1, \epsilon}^\iota=&b'\left(\partial_\lambda^3\psi-r_{3,0,\epsilon}^\iota\right)\\
&+\left(-\frac{b''}{b'}\psi+\frac{\omega_{0k}}{b'}\right)\frac{(1-\chi_{\ast,\delta_0\slash10}(y))}{(b-\lambda+i\iota\epsilon)^2}\\
&+\left\{\begin{aligned}
&\frac{b''}{(b')^2}\partial_y\psi+\frac{\omega_{0k}'}{(b')^2}
+\left[-\frac{b'''}{(b')^2}+\frac{(b'')^2}{(b')^3}\right]\psi\\
&-\frac{b''}{(b')^3}\omega_{0k}-\frac{2b''}{(b')^2}D_\lambda\psi
\end{aligned}\right\}\frac{1-\chi_{\ast,\delta_0\slash10}(y)}{b-\lambda+i\iota\epsilon}\\
            &+\left\{\begin{aligned}
            &\frac{3b''}{(b')^4}\omega_{0k}'+\frac{k^2(b')^2b''+(b')^2b^{(4)}-4b'b''b'''+3(b'')^3}{(b')^5}\psi\\
            &-\frac{k^2(b')^2-b'b'''+3(b'')^2}{(b')^5}\omega_{0k}+\frac{2b'b'''-3(b'')^2}{(b')^4}D_\lambda\psi\\
            &+\frac{b''}{(b')^3}D_\lambda^2\psi-\frac{\omega_{0k}''}{(b')^3}
            \end{aligned}
            \right\}\\
&\qquad\times(1-\chi_{\ast,\delta_0\slash10}(y))\log(b-\lambda+i\iota\epsilon),
        \end{split}
    \end{equation}
    where $r_{3,0,\epsilon}^\iota(y,\lambda):=\partial_\lambda^3 \psi_{k, \epsilon}^\iota   - \mathcal{S}_{3, 0, \epsilon}^\iota$ with $\|r_{3,0,\epsilon}^\iota\|_{H^1_k} \lesssim  |k|^{-1/2}\|\omega_{0k}\|_{H^4_k}$ from Lemma \ref{ndpsi_l3}.
    Then $\partial_\lambda^2D_\lambda\psi_{k, \epsilon}^\iota- \mathcal{S}_{2,1, \epsilon}^\iota$ satisfies 
    \begin{equation}
        \left(\partial_y^2-k^2-\frac{b''(y)}{b(y)-\lambda+i\iota\epsilon}\right)\left(\partial_\lambda^2D_\lambda\psi_{k, \epsilon}^\iota- \mathcal{S}_{2,1, \epsilon}^\iota\right)=\mathcal{R}_{2,1,\epsilon}^{\iota}(y,\lambda).
    \end{equation}
                      
                       
                                                                                                                                                                                            
                                                                                                                                                                    
                                     
                                                                                                                            
                                                                                                          
                                                                         
                                     
                                                                                                                                                        
                                                                                                                                  
                                                                     
                                                                                                                                                                                                                                                      
                     
                    
                                                                                                              
    Here $\mathcal{R}^\iota_{2,1,\epsilon}$ can be regrouped as 
    \begin{equation}
        \begin{split}
            \mathcal{R}_{2,1,\epsilon}^{\iota}(y,\lambda)=&c_1(y)\frac{\log(b(y)-\lambda+i\iota\epsilon)}{b(y)-\lambda+i\iota\epsilon}+\frac{c_2(y)+\mathfrak{c}_1(y)\partial_yD_\lambda^2\psi+\mathfrak{c}_2(y)\partial_yD_\lambda\psi+\mathfrak{c}_3(y)\partial_y\psi}{b(y)-\lambda+i\iota\epsilon}\\
            &+c_3(y)\log(b(y)-\lambda+i\iota\epsilon)+c_4(y),
        \end{split}
    \end{equation}
    with $|k|\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_3\|_{L^2}+\|c_{4}\|_{L^2}\lesssim\|\omega_{0k}\|_{H^4_k}$. 
    The conclusion follows directly from Lemmas \ref{ndraygeneral}, \ref{ndrayg}.

Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma\backslash \cup_{j}\Sigma_{j, \delta_0},\, \epsilon \in (0, \epsilon_0),\, \iota\in\{\pm\}$, and let $\psi_{k,\epsilon}^{\iota}(y,\lambda)$ be as defined in \eqref{F7}. 
    For $y\in \mathbb{T}$, set
    \begin{equation}\label{ndS12}
        \begin{split}
            \mathcal{S}_{1, 2, \epsilon}^\iota(y, \lambda) &:= \left[
                \begin{aligned}
                    &C_1(y)D_\lambda^2\psi(y,\lambda)+C_2(y)D_\lambda\psi(y,\lambda)\\
                    &+C_3(y)\psi(y,\lambda)+\Omega_{0k}(y)
                \end{aligned}    
            \right](1-\chi_{\ast,\delta_0\slash10}(y))\log(b(y)-\lambda+i\iota\epsilon),
        \end{split}
    \end{equation}
    where 
    \begin{equation}
        \begin{split}
            &\Omega_{0k}(y)=C_4(y)\omega_{0k}''(y)+C_{5}(y)\omega_{0k}'(y)+C_{6}(y)\omega_{0k}(y), \\
            &C_1(y)=-\frac{b''}{(b')^2},\quad\ C_2(y)=-\frac{2b'''}{(b')^2}+\frac{4(b'')^2}{(b')^3},\quad\ C_3(y)=-\frac{b^{(4)}}{(b')^2}+\frac{6b''b'''}{(b')^3}-\frac{6(b'')^3}{(b')^4},\\
            &C_4(y)=\frac{1}{(b')^2},\quad\ C_5(y)=-\frac{4b''}{(b')^3},\quad\ C_6(y)=-\frac{2b'''}{(b')^3}+\frac{6(b'')^2}{(b')^4}.
        \end{split}
    \end{equation}
    Then we have the bounds
    \begin{equation}\label{ndlamD2:bdd}
        \norm{\partial_\lambda D_\lambda^2 \psi_{k, \epsilon}^\iota   - \mathcal{S}_{1, 2, \epsilon}^\iota }_{H^1_k} \lesssim  \frac{\big\|\omega_{0k}\big\|_{H^4_k}}{|k|^{1/2}}.
    \end{equation}

Similar to the arguments in Lemma \ref{ndpsi_lD}, one can rewrite $\mathcal{S}_{1,2, \epsilon}^\iota$ as follows
    \begin{equation*}
        \begin{split}
            \mathcal{S}_{1,2, \epsilon}^\iota=&-(b')^2(\partial_\lambda^3\psi-r_{3,0,\epsilon}^\iota)+(b''\psi-\omega_{0k})\frac{1-\chi_{\ast,\delta_0\slash10}(y)}{(b-\lambda+i\iota\epsilon)^2}+2b'(\partial_\lambda^2D_\lambda\psi-r_{2,1,\epsilon}^\iota)\\
            &+b''(\partial_\lambda^2\psi-r_{2,0,\epsilon}^\iota)+\frac{b''}{b'}(D_\lambda\psi-\partial_y\psi)\frac{1-\chi_{\ast,\delta_0\slash10}(y)}{b-\lambda+i\iota\epsilon}\\
            &-\frac{k^2(b''\psi-\omega_{0k})}{(b')^2}(1-\chi_{\ast,\delta_0\slash10}(y))\log(b-\lambda+i\iota\epsilon),\\
        \end{split}
    \end{equation*}
    where $r_{2,1,\epsilon}^\iota(y,\lambda):=\partial_\lambda^2 D_\lambda \psi_{k, \epsilon}^\iota   - \mathcal{S}_{2, 1, \epsilon}^\iota$ with $\|r_{2,1,\epsilon}^\iota\|_{H^1_k} \lesssim  |k|^{-1/2}\|\omega_{0k}\|_{H^4_k}$ from Lemma \ref{ndpsi_l2D}.
    Then $\partial_\lambda D_\lambda^2\psi_{k, \epsilon}^\iota- \mathcal{S}_{1,2, \epsilon}^\iota$ satisfies 
    \begin{equation}
        \left(\partial_y^2-k^2-\frac{b''(y)}{b(y)-\lambda+i\iota\epsilon}\right)\left(\partial_\lambda D_\lambda^2\psi_{k, \epsilon}^\iota- \mathcal{S}_{1,2, \epsilon}^\iota\right)=\mathcal{R}_{1,2,\epsilon}^{\iota}(y,\lambda).
    \end{equation}
                                                                                                               
    $\mathcal{R}^\iota_{1,2,\epsilon}$ is of the form
    \begin{equation}
        \begin{split}
            \mathcal{R}_{1,2,\epsilon}^{\iota}(y,\lambda)=&c_1(y)\frac{\log(b(y)-\lambda+i\iota\epsilon)}{b(y)-\lambda+i\iota\epsilon}+\frac{c_2(y)+\mathfrak{c}_1(y)\partial_yD_\lambda^2\psi+\mathfrak{c}_2(y)\partial_yD_\lambda\psi+\mathfrak{c}_3(y)\partial_y\psi}{b(y)-\lambda+i\iota\epsilon}\\
            &+c_3(y)\log(b(y)-\lambda+i\iota\epsilon)+c_4(y),
        \end{split}
    \end{equation}
    with $|k|\|c_1\|_{H^1_k}+\|c_2\|_{H^1_k}+\|c_3\|_{L^2}+\|c_{4}\|_{L^2}\lesssim\|\omega_{0k}\|_{H^4_k}$. 
    The conclusion follows directly from Lemmas \ref{ndraygeneral}, \ref{ndrayg}.

\label{g:bdds}
    We have the following bounds for $g^\iota_{k,\epsilon}(y,\lambda)$.
    \begin{subequations}
         \begin{align}
    |g^\iota_{k,\epsilon}(y,\lambda)| + |\partial_\lambda g^\iota_{k,\epsilon}(y,\lambda)| + |\partial_\lambda^2 g^\iota_{k,\epsilon}(y,\lambda)| + |\partial_\lambda^3 g^\iota_{k,\epsilon}(y,\lambda)| &\lesssim \frac{\norm{\omega_{0k}}_{H_k^4} }{|k|^{3/2}}, \\
     |\partial_yg^\iota_{k,\epsilon}(y,\lambda)| + |D_\lambda g^\iota_{k,\epsilon}(y,\lambda)| +  |\partial_\lambda D_\lambda g^\iota_{k,\epsilon}(y,\lambda)| +  |\partial_\lambda^2 D_\lambda g^\iota_{k,\epsilon}(y,\lambda)| &\lesssim \frac{\norm{\omega_{0k}}_{H_k^4}   }{|k|^{1/2}}, \\ 
    \norm{\partial_y^2g^\iota_{k,\epsilon}(y,\lambda)}_{L^2} + \norm{D_\lambda^2g^\iota_{k,\epsilon}(y,\lambda)}_{L^2} + \norm{\partial_\lambdaD_\lambda^2g^\iota_{k,\epsilon}(y,\lambda)}_{L^2}  &\lesssim \norm{\omega_{0k}}_{H_k^4}. 
    \end{align}
    \end{subequations}
 Additionally, when $|k \delta(\Lambda)| \gtrsim 1$, we have the following bound for $\alpha \in \{0,1 \}$.
\begin{subequations}
\begin{equation}
\begin{split}
&\left|\int_\mathbb{T}\varrho_{j,k}^\alpha(y;\Lambda)\partial_y^\alpha\mathcal G_k^j(y,z;\Lambda)
\sum_{r=0}^3|\partial_\lambda^r g_{k,\epsilon}^\iota(z,\lambda)|\,dz\right|\\
&\qquad\lesssim\frac{\|\omega_{0k}\|_{H_k^4}}{|k|^{7/2}},
\end{split}
\end{equation}
\begin{equation}
\begin{split}
&\left|\int_\mathbb{T}\varrho_{j,k}^\alpha(y;\Lambda)\partial_y^\alpha\mathcal G_k^j(y,z;\Lambda)
\left(|\partial_y g_{k,\epsilon}^\iota(z,\lambda)|+\sum_{r=0}^2|\partial_\lambda^rD_\lambda g_{k,\epsilon}^\iota(z,\lambda)|\right)\,dz\right|\\
&\qquad\lesssim\frac{\|\omega_{0k}\|_{H_k^4}}{|k|^{5/2}},
\end{split}
\end{equation}
\begin{equation}
\begin{split}
&\left|\int_\mathbb{T}\varrho_{j,k}^\alpha(y;\Lambda)\partial_y^\alpha\mathcal G_k^j(y,z;\Lambda)
\left(|\partial_y^2g_{k,\epsilon}^\iota(z,\lambda)|+|D_\lambda^2g_{k,\epsilon}^\iota(z,\lambda)|
+|\partial_\lambdaD_\lambda^2g_{k,\epsilon}^\iota(z,\lambda)|\right)\,dz\right|\\
&\qquad\lesssim\frac{\|\omega_{0k}\|_{H_k^4}}{|k|^{3/2}}.
\end{split}
\end{equation}
\end{subequations}

\label{a:bdds}
    We have the following bounds on $a_\epsilon^\iota(y)$ for $y \in [\delta(\Lambda), \delta_0]$, $\lambda \in \Sigma_{j, \delta_0}\setminus\{b(y_{j*})\}$, $\epsilon \in (0, \epsilon_0)$ and $\alpha \in [0,4]\cap \mathbb{Z}$:
\begin{subequations}
   \begin{align}
        |  \partial_y^\alpha( a_\epsilon^\iota(y) -1)| &\lesssim \varrho^{1-\alpha}(y;\Lambda), \label{a_y}\\
    |\partial_\lambda^\alpha  (a_\epsilon^\iota(y) -1)| &\lesssim \varrho^{1- 2\alpha}(y;\Lambda), \label{a_lambda} \\
    | D_{j,\lambda}^\alpha (a_\epsilon^\iota(y) -1) | &\lesssim \varrho^{1-\alpha}(y;\Lambda), \label{a_good} \\
   \lim_{\epsilon \to 0} \partial_\lambda^\alpha (a_\epsilon^+(y) - a_\epsilon^-(y)) &= 0, \label{a_dif}
   \end{align} 
\end{subequations}
where 
    \begin{align}
    \label{djgood}
        D_{j,\lambda} : = b_j'(y) \partial_\lambda + \partial_y. 
    \end{align}

For $y \in [ \delta_0/2, \delta_0]$, the bounds are immediate so we consider the more difficult case where $y \in [\delta(\Lambda), \delta_0/2]$.
We introduce the quantity 
\begin{align}
    d(y) :=  b_j(-y) - b_j(y).
\end{align}
By the assumption on $b$ and Taylor's theorem, we have
\begin{align}
    |d(y)| \lesssim |y|^3.
\end{align}
We wish to expand $H_{l, \epsilon}^\iota(-y)$ in terms of $H_{r, \epsilon}^\iota(y)$ and use $d$ to quantify the error. We first write 
\begin{align}
    \varphi_{\epsilon}^\iota(-y) = b_j(-y) - \lambda + i \iota \epsilon = \varphi_{\epsilon}^\iota(y) + d(y).
\end{align}
Therefore,
\begin{align}
    H_{l, \epsilon}^\iota(-y) &= \varphi_{\epsilon}^\iota(-y) \int_{-\delta_0}^{-y} \frac{ds}{(\varphi_{\epsilon}^\iota)^2(s)} = (\varphi_{\epsilon}^\iota(y) + d(y)) \int_{-\delta_0}^{-y}\frac{ds}{(\varphi_{\epsilon}^\iota(-s) - d(s))^2 } \\
    &= \left (\varphi_{\epsilon}^\iota(y) + d(y) \right) \left(    \int_{-\delta_0}^{-y} \frac{ds}{(\varphi_{\epsilon}^\iota)^2(-s)}   + \int_{-\delta_0}^{-y} \frac{1}{(\varphi_{\epsilon}^\iota)^2(-s)} \left[ \left(\sum_{n \geq 0} \frac{d^n(s)}{(\varphi_{\epsilon}^\iota)^n(-s)} \right)^2    -1    \right] ds    \right) \\
    &= H_{r, \epsilon}^\iota(y) + d(y)\int_y^{\delta_0}\frac{ds}{
    (\varphi_{\epsilon}^\iota)^2(s)}  + \varphi_{\epsilon}^\iota(y ) \int_{y}^{\delta_0} \frac{1}{(\varphi_{\epsilon}^\iota)^2(s)}
    \left[ \left(\sum_{n \geq 0} \frac{d^n(-s)}{(\varphi_{\epsilon}^\iota)^n(s)} \right)^2    -1    \right] ds   \\
    &+ d(y) \int_{y}^{\delta_0} \frac{1}{(\varphi_{\epsilon}^\iota)^2(s)} \left[ \left(\sum_{n \geq 0} \frac{d^n(-s)}{(\varphi_{\epsilon}^\iota)^n(s)} \right)^2    -1    \right] ds\\
    &= H_{r, \epsilon}^\iota(y) + R(y),
\end{align}
where 
\begin{align}
    R(y) &:=  d(y)\int_y^{\delta_0}\frac{ds}{
    (\varphi_{\epsilon}^\iota)^2(s)}  + \varphi_{\epsilon}^\iota(y ) \int_{y}^{\delta_0} \frac{1}{(\varphi_{\epsilon}^\iota)^2(s)}
    \left[ \left(\sum_{n \geq 0} \frac{d^n(-s)}{(\varphi_{\epsilon}^\iota)^n(s)} \right)^2    -1    \right] ds \\
    &+ d(y) \int_{y}^{\delta_0
    } \frac{1}{(\varphi_{\epsilon}^\iota)^2(s)} \left[ \left(\sum_{n \geq 0} \frac{d^n(-s)}{(\varphi_{\epsilon}^\iota)^n(s)} \right)^2    -1    \right] ds.
\end{align}

Therefore,
\begin{align}
    a_\epsilon^\iota(y) - 1 = \frac{H_{r, \epsilon}^\iota(y) + R(y)}{H_{r, \epsilon}^\iota(y)} -1 = \frac{R(y)}{H_{r, \epsilon}^\iota(y)}. 
\end{align}



By definition of $\delta(\Lambda), \delta_0$, we have that 
\begin{align}
  \frac{|b_j''(0)|y^2}{4} \lesssim  |\varphi_{\epsilon}^\iota(y)| \lesssim |b_j''(0)|y^2  , y \in [\delta(\Lambda) , \delta_0   ].
\end{align}
Therefore,  
\begin{align}
    |\partial_y^\alpha R(y)| &\lesssim |y|^{-\alpha},\\
    |\partial_y^\alpha (H_{r, \epsilon}^\iota)^{-1}(y)| & \lesssim |y|^{1 -\alpha},\\
    |\partial_\lambda^\alpha R(y)| &\lesssim |y|^{-2\alpha},\\
    |\partial_\lambda^\alpha (H_{r, \epsilon}^\iota)^{-1}(y)| &\lesssim |y|^{1 -2\alpha}.
\end{align}
The bounds then follow from the product rule and that  $y \approx \varrho(y;\Lambda)$ for $y \in [\delta(\Lambda), \delta_0/2]$. 

Finally, we have
\begin{align}
    a_\epsilon^+(y) - a_\epsilon^-(y) &= \frac{ H_{r, \epsilon}^-(y )H_{l, \epsilon}^+(-y)  - H_{r, \epsilon}^+(y)H_{l, \epsilon}^-(-y)    }{H_{r, \epsilon}^-(y)  H_{r, \epsilon}^+(y)   }. 
\end{align}
The proof then follows from the following estimates, valid for $y \in [\delta(\Lambda), \delta_0/2], \alpha \in \{0,1,2,3,4\}$
\begin{align}
    \left| \varrho^\alpha(y;\Lambda ) \partial_y^\alpha \frac{1}{H_{r, \epsilon}^\iota(y)  H_{r, \epsilon}^\iota(y)} \right| \lesssim \varrho^2(y;\Lambda),
\end{align}
\begin{align}
    \left| \varrho^\alpha(y;\Lambda ) \partial_y^\alpha\left( \int_y^{\delta_0} \frac{ds}{(\varphi_{\epsilon}^+)^2(s)} - \int_y^{\delta_0} \frac{ds}{ (\varphi_{\epsilon}^-)^2(s) } \right) \right| \lesssim  \frac{\epsilon}{\varrho^5(y; \Lambda)}, 
\end{align}
and the product rule.

\label{lem:phi-bounds}
Let $\Phi_\epsilon^\iota$ solve \eqref{Inner_problem}. For $\lambda \in \Sigma_{j,\delta_0} \setminus \{b(y_{j*})\},  \epsilon \in (0, \epsilon_0)$, $\theta \in (0,1/4]$, and $\alpha \in \{ 0,1\} $ we have
    \begin{subequations}
    \label{phi:lam}
  \begin{align}
     | \varrho^\alpha(y;\Lambda) \partial_y^\alpha \Phi_\epsilon^\iota(y,\lambda )| &\lesssim \varrho^{2- \theta}(y; \Lambda), \\
 |\varrho^\alpha(y;\Lambda) \partial_y^\alpha \partial_\lambda \Phi_\epsilon^\iota(y,\lambda )|  &\lesssim  \varrho^{- \theta}(y; \Lambda),   \\
 |\varrho^\alpha(y;\Lambda) \partial_y^\alpha \partial_\lambda^2 \Phi_\epsilon^\iota(y,\lambda )|  &\lesssim \frac{1}{\varrho(y;\Lambda) \delta(\Lambda)}, \\
|\varrho^\alpha(y;\Lambda) \partial_y^\alpha \partial_\lambda^3 \Phi_\epsilon^\iota(y,\lambda )|   &\lesssim  \frac{1}{\varrho(y;\Lambda) \delta^{3}(\Lambda)}, \\
|\varrho^\alpha(y;\Lambda) \partial_y^\alpha \partial_\lambda^4 \Phi_\epsilon^\iota(y,\lambda )|   &\lesssim  \frac{1}{\varrho(y;\Lambda) \delta^{5}(\Lambda)},
    \end{align}
    \end{subequations}
  \begin{subequations}
  \label{phi:good}
  \begin{align}
 |\varrho^\alpha(y;\Lambda) \partial_y^\alpha D_{j,\lambda} \Phi_\epsilon^\iota(y,\lambda )|  &\lesssim \varrho(y;\Lambda),   \\
 |\varrho^\alpha(y;\Lambda) \partial_y^\alpha \partial_\lambda D_{j,\lambda}   \Phi_\epsilon^\iota(y,\lambda )|  &\lesssim  \frac{1}{\delta(\Lambda)}, \\
 |\varrho^\alpha(y;\Lambda) \partial_y^\alpha D_{j,\lambda}^2 \Phi_\epsilon^\iota(y,\lambda )|  &\lesssim  \frac{\varrho(y;\Lambda)}{\delta(\Lambda)}, \\
 |\varrho^\alpha(y;\Lambda) \partial_y^\alpha \partial_\lambda D_{j,\lambda}^2 \Phi_\epsilon^\iota(y,\lambda )|  &\lesssim  \frac{\varrho(y;\Lambda)}{\delta^3(\Lambda)}.
    \end{align}
    \end{subequations}

The proof follows by direct calculation. We briefly highlight the origin of the $\theta$ factor. Assume that $y  > 4\delta(\Lambda)$. From \eqref{in:green}, we have 
\begin{align}
    |\Phi_\epsilon^\iota (y,\lambda) - \varphi_\epsilon^\iota(y)\int_{y}^{\delta_0}  H_{l, \epsilon}^\iota(-z) dz| \lesssim \varrho^2(y; \Lambda). 
 \end{align}
 However,  for $y \in (4 \delta(\Lambda), \delta_0/2)$
\begin{align}
\label{log:loss}
    |\int_{y}^{\delta_0}  H_{l, \epsilon}^\iota(-z) dz| \approx |\log \varrho(y; \Lambda)|, \quad  |\varphi_\epsilon^\iota(y)| \approx \varrho^2(y;\Lambda).
\end{align}
Instead of propagating a logarithmic factor through the estimates, we opt to track an algebraic loss encoded by $\theta$. This logarithmic correction disappears after the second spectral derivative because $\partial_\lambda^2 \varphi_\epsilon^\iota(y) = 0$.

\label{phi:van}

Let $\Phi_\epsilon^\iota$ solve \eqref{Inner_problem} with $\lambda \in \Sigma_{j,\delta_0} \setminus \{b(y_{j*})\}$, $\epsilon \in (0, \epsilon_0)$, and $\theta \in (0,1/4]$. The following limits hold. 
   \begin{subequations}
       \begin{align}
       \lim_{\epsilon \to 0} D_{j, \lambda}^\alpha \Phi_\epsilon^\iota(y_\lambda, \lambda) &= 0, \quad b_j(y_\lambda) = \lambda , \alpha \in \{ 0,1,2\},\label{lem:phi1}\\
        \lim_{\epsilon \to 0}     \partial_y^\alpha \partial_\lambda^\beta (\Phi_\epsilon^+(y,\lambda ) - \Phi_\epsilon^-(y,\lambda ) )    &= 0, \quad   \alpha \in \{ 0,1\}, \beta \in \{0,1,2,3\}, \label{lem:phi2}\\
        \lim_{\epsilon \to 0}     D_{j,\lambda}^\alpha (\Phi_\epsilon^+(y,\lambda ) - \Phi_\epsilon^-(y,\lambda ) )    &= 0, \quad  \alpha \in \{0,1,2\}. \label{lem:phi3}
   \end{align}
   \end{subequations}
   The convergence is understood in a pointwise sense for fixed $y,\lambda$.

The proof of \eqref{lem:phi1} follows by a direct calculation using \eqref{Phi:rep}. The proof of \eqref{lem:phi2} follows from the observation that 
    \begin{align}
        \Phi_\epsilon(y, \lambda) := \Phi_\epsilon^+(y, \lambda) - \Phi_\epsilon^-(y, \lambda)
    \end{align}
    satisfies the equation 
    \begin{align}
        -\partial_y^2 \Phi_\epsilon + \frac{b_j''(y)}{b_j(y) - \lambda + i \epsilon} \Phi_\epsilon &= - \Phi_\epsilon^-(y,\lambda) b_j''(y) \left( \frac{1}{b_j(y) - \lambda + i \epsilon } - \frac{1}{b_j(y) -\lambda - i \epsilon   } \right) \\
        &+ (a_\epsilon^+(y ) - a_\epsilon^-(y))(1 - \chi_{\delta(\Lambda)}(y))\mathbbm{1}_{y\geq 0}.
     \end{align}
     By Lemma \ref{a:bdds} and \eqref{lem:phi1} we have the following convergence in the sense of distributions: 
     \begin{align}
        \lim_{\epsilon \to 0}  \frac{2 i \epsilon \Phi_\epsilon^-(y,\lambda) b_j''(y)  }{ (b_j(y) - \lambda)^2 + \epsilon^2 }  + (a_\epsilon^+(y ) - a_\epsilon^-(y))(1 - \chi_{\delta(\Lambda)}(y))\mathbbm{1}_{y\geq 0} = 0.
     \end{align}
    The case for higher vanishing then follows by the bounds in \eqref{phi:lam}, \eqref{phi:good} and the assumption that $\lambda \neq b(y_{j*})$.

\label{R00:bdd}
Let $\lambda \in \Sigma_{j,\delta_0} \setminus \{b(y_{j*})\},  \epsilon \in (0, \epsilon_0), \theta \in (0,1/4], \iota\in \{-, +\}$, and  $ \mathcal{R}_{0, 0, \epsilon}^\iota(y,\lambda)$ be defined as in \eqref{eq:Erhs}. Then   the following bounds hold for $|y| \lesssim |k|^{-1}, |k |\delta(\Lambda) \ll 1$ with a constant depending on $\theta$.
               
                                                                                                                                 
             
\begin{subequations}\label{R00:lam}
\begin{align}
    |\mathcal{R}_{0,0,\epsilon}^\iota(y,\lambda)| &\lesssim \frac{  \norm{\omega_{0k}}_{H_k^4}   }{|k|}  \left(   \frac{\mathbbm{1}_{|y| \lesssim \delta(\Lambda)   }}{|k|^{1/2}} +  \varrho^{1/2}(y;\Lambda) +   |k|^{3/2}\varrho^{2 - \theta}(y;\Lambda) \right), \\
    |\partial_\lambda \mathcal{R}_{0, 0, \epsilon}^\iota(y,\lambda)| &\lesssim \frac{ \norm{\omega_{0k}}_{H_k^4}   }{|k|^{3/2}}  \left(   \frac{\mathbbm{1}_{|y| \lesssim \delta(\Lambda)   } }{\delta^2(\Lambda)} + \frac{1}{\varrho(y;\Lambda)} +  \frac{|k|^{2}}{\varrho^{ \theta}(y;\Lambda)} \right), \\
    |\partial_\lambda^2 \mathcal{R}_{0, 0, \epsilon}^\iota(y,\lambda)| &\lesssim    \frac{ \norm{\omega_{0k}}_{H_k^4}   }{|k|^{3/2}}  \left(   \frac{\mathbbm{1}_{|y| \lesssim \delta(\Lambda)   } }{\delta^4(\Lambda)} + \frac{1}{\varrho^3(y;\Lambda)} +  \frac{|k|^{2}}{\delta(\Lambda)\varrho(y;\Lambda)} \right), \\
    |\partial_\lambda^3 \mathcal{R}_{0, 0, \epsilon}^\iota(y,\lambda)|  &\lesssim    \frac{ \norm{\omega_{0k}}_{H_k^4}   }{|k|^{3/2}}  \left(   \frac{\mathbbm{1}_{|y| \lesssim \delta(\Lambda)   } }{\delta^6(\Lambda)} + \frac{1}{\varrho^5(y;\Lambda)} +  \frac{|k|^{2}}{\delta^3(\Lambda)\varrho(y;\Lambda)} \right),
\end{align}
\end{subequations}
\begin{subequations}\label{R00:good}
\begin{align}
    |D_{j,\lambda} \mathcal{R}_{0, 0, \epsilon}^\iota(y,\lambda)| &\lesssim \frac{\norm{\omega_{0k}}_{H_k^4}  }{|k|^{1/2}} \left(   1 +   \frac{\mathbbm{1}_{|y| \lesssim \delta(\Lambda) }}{|k| \delta(\Lambda)}  + |k| \varrho(y;\Lambda) +\mathbbm{1}_{|y| \approx |k|^{-1}} |k|^{\theta} \right), \\
    |\partial_\lambda D_{j,\lambda} \mathcal{R}_{0, 0, \epsilon}^\iota(y,\lambda)| &\lesssim \frac{\norm{\omega_{0k}}_{H_k^4}  }{|k|^{1/2}} \left(   \frac{\mathbbm{1}_{|y| \lesssim \delta(\Lambda) }}{|k| \delta^3(\Lambda)}   +  \frac{|k|}{\delta(\Lambda)} + |k|^{2 + \theta }\mathbbm{1}_{|y| \approx |k|^{-1}}  \right), \\
    |\partial_\lambda^2 D_{j,\lambda} \mathcal{R}_{0, 0, \epsilon}^\iota(y,\lambda)| &\lesssim \frac{\norm{\omega_{0k}}_{H_k^4}  }{|k|^{1/2}} \left(   \frac{\mathbbm{1}_{|y| \lesssim  \delta(\Lambda) }}{|k|\delta^5(\Lambda)}   +  \frac{|k|}{\delta^3(\Lambda)}  \right),
\end{align}
\begin{equation}
\begin{aligned}
&|D_{j,\lambda}^2 ( \mathcal{R}_{0, 0, \epsilon}^\iota(y,\lambda) - g^\iota_{k,\epsilon}(y + y_{j*},\lambda))| \\
     &\lesssim \norm{\omega_{0k}}_{H_k^4}   \left(  \frac{\mathbbm{1}_{|y| \approx \delta(\Lambda)  }}{\delta^2(\Lambda) |k|^{3/2} }   + \frac{1}{|k|^{3/2} \varrho(y; \Lambda)  }   + \frac{|k|^{1/2} \varrho(y;\Lambda) }{\delta(\Lambda)} + |k|^{1/2 + \theta} \mathbbm{1}_{|y| \approx |k|^{-1}}      \right),
\end{aligned}
\end{equation}
\begin{equation}
\begin{aligned}
&|\partial_\lambda D_{j,\lambda}^2 ( \mathcal{R}_{0, 0, \epsilon}^\iota(y,\lambda) - g^\iota_{k,\epsilon}(y + y_{j*},\lambda))| \\
     &\lesssim \norm{\omega_{0k}}_{H_k^4}   \left(  \frac{\mathbbm{1}_{|y| \approx \delta(\Lambda)  }}{\delta^4(\Lambda) |k|^{3/2} } + \frac{1}{|k|^{3/2} \varrho^3(y; \Lambda)  }   + \frac{|k|^{1/2} \varrho(y;\Lambda) }{\delta^3(\Lambda)} + |k|^{5/2 + \theta} \mathbbm{1}_{|y| \approx |k|^{-1}}      \right).
\end{aligned}
\end{equation}
\end{subequations}

The proof follows by direct computation using Lemmas \ref{g:bdds}, \ref{a:bdds}, and \ref{lem:phi-bounds}.


 

