\label{dint}
    Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma_{j, \delta_0} \setminus \{b(y_{j*})\}$, $\iota\in\{\pm\}, \epsilon\in(0,\epsilon_0)$, $\alpha \in\{0,1,2,\cdots\}$, and that $\sigma_1 \in [0,1], \sigma_2\in [-2,0], \sigma_1 + \sigma_2 \in [-2, 1]$. The following implicit constants are allowed to depend on $\alpha$. 
    In this lemma, functions on $S_{3\delta(\Lambda)}^j$ are extended by zero to $\mathbb{T}$, and the local $H^1$ functions are assumed to have zero endpoint traces.
    \begin{enumerate}
    \item For any function $f(y)\in L^2(S_{3 \delta(\Lambda)}^j)$ with $\text{supp }f \subseteq S_{3 \delta(\Lambda)}^j$, we have the following estimates.
                                     
                                                                                                                                                                                                  
                    
    \begin{align}\label{dlogl2}
        &\left\|\int_{\mathbb{T}} \mathcal{G}_{k}^j(y,z, \Lambda) \chi_{ j, \delta(\Lambda) }(z) f(z)\log^\alpha \left( \frac{b(z)-\lambda+i\iota\epsilon   }{\delta^2(\Lambda)} \right)dz\right\|_{X^{\sigma_1, \sigma_2}} \\
        &\lesssim \norm{f}_{L^2(S_{3 \delta(\Lambda)}^j)} \delta^{\sigma_1}(\Lambda)d_{j,k}^{\sigma_2 + 3/2}.
        \notag
    \end{align}
                      
                                                                                                                                                                                                  
                    
                      
                                                                                                                                                                                                                                                            
                    
    \item For any function $f(y) \in H^1(S_{3 \delta(\Lambda)}^j)$  with $\text{supp }f \subseteq S_{3 \delta(\Lambda)}^j$
                   
                                                                                                        
                 
    we have the following estimates.
                                      
                                                                                                                                                                                                                                             
                    
                                                 
    \begin{align}\label{dfracl2}
        \left\|\int_{\mathbb{T}}\mathcal{G}_k^j(y,z, \Lambda ) \chi_{j,\delta(\Lambda)}(z)f(z)\frac{\log^\alpha( \frac{b(z)-\lambda+i\iota\epsilon}{\delta^2(\Lambda)})}{b(z)-\lambda+i\iota\epsilon}dz\right\|_{X^{\sigma_1, \sigma_2}}
        \lesssim \norm{f}_{X^{0,0}} \delta^{\sigma_1}(\Lambda) d_{j,k}^{\sigma_2}.
    \end{align}
   \item For a  function $f(y,\lambda ) \in H^1(\mathbb{T})$, we assume that there exist functions  $c_1(y,\lambda), c_2(y,\lambda) \in H^1(S_{3 \delta(\Lambda)}^j)$, $c_3(y,\lambda), c_4(y,\lambda) \in L^2(S_{3 \delta(\Lambda)}^j)$ with support in $ S_{3 \delta(\Lambda)}^j$, such that in a distributional sense we have  
   \begin{align}\label{drayf}
       &\left(-\partial_y^2+k^2+\frac{b''(y)}{b(y)-\lambda+i\iota\epsilon}\right)f(y,\lambda) \\
            &= c_1(y,\lambda)\frac{\log \frac{(b(y)-\lambda+i\iota\epsilon)}{\delta^2(\Lambda)}}{b(y)-\lambda+i\iota\epsilon}+c_2(y,\lambda)\frac{1}{b(y)-\lambda+i\iota\epsilon}
            +c_{3}(y,\lambda)\log^\alpha \frac{(b(y)-\lambda+i\iota\epsilon)}{\delta^2(\Lambda)}  +c_4(y,\lambda). \notag
   \end{align}
    Then we have the following:
 \begin{align}\label{dfracl3}
        &\left\|\int_{\mathbb{T}}\mathcal{G}_k^j(y,z, \Lambda ) \chi_{j,\delta}^*(z)\frac{\partial_z f(z)}{b(z)-\lambda+i\iota\epsilon}dz\right\|_{X^{\sigma_1, \sigma_2}}\\
        &\lesssim \delta^{\sigma_1}(\Lambda)d_{j,k}^{\sigma_2 -1} \left[ \norm{c_1}_{X^{0,0}} + \norm{c_2}_{X^{0,0}} +         \delta^{1/2}(\Lambda) d_{j,k} (  \norm{c_3}_{L^2(S_{3 \delta(\Lambda)}^j)}  + \norm{c_4}_{L^2(S_{3 \delta(\Lambda)}^j)}  )  \right]. \notag
    \end{align}
    
    \end{enumerate}

The proof of \eqref{dlogl2} immediately follows from the Green-function bounds and the allowed ranges for $\sigma_1, \sigma_2$. The proof of \eqref{dfracl2} follows by the proof of Lemma \ref{DeC4} and the additional identity 
    \begin{align}
       \partial_y \log^{\alpha +1 }  \left( \frac{b(y) - \lambda + i \epsilon}{\delta^2(\Lambda)}  \right)  = (\alpha + 1) \frac{b'(y)}{b(y) - \lambda + i \epsilon} \log^{\alpha }  \left( \frac{b(y) - \lambda + i \epsilon}{\delta^2(\Lambda)}  \right),
    \end{align}
  to handle the extra logarithmic factor appearing relative to those appearing in $T_\Theta$ in \eqref{DeC3}. To prove  \eqref{dfracl3}, observe by extending $c_j$ by 0, we can apply Proposition \ref{DeC7} which yields  
  \begin{align}
      \norm{f}_{X^{0,0}} \lesssim \norm{c_1}_{X^{0,0}} + \norm{c_2}_{X^{0,0}} + \delta^{1/2}(\Lambda)d_{j,k}(\norm{c_3}_{L^2(S_{3 \delta(\Lambda)}^j) } + \norm{c_4}_{L^2(S_{3 \delta(\Lambda)}^j) }).
  \end{align}
 Integrating by parts, using \eqref{drayf}, and \eqref{dfracl2} with $\alpha = 1,2$ then imply the desired result.

\label{DCM1}
Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma_{j, \delta_0} \setminus \{b(y_{j*}) \}$, $\iota\in\{\pm\}, \epsilon \in (0, \epsilon_0) $. Then for any $\theta \in (0, 1/4]$ we have the following bound: 
\begin{equation}\label{DCM2}
\begin{split}
\norm{\digamma_{k, \epsilon}^\iota }_{X^{0, -2}} \lesssim \frac{\big\|\omega_{0k}\big\|_{H^4_k}}{|k|^{3/2- \theta}}.
\end{split}
\end{equation}

From \eqref{BDC2} and \eqref{E:eq} we have 
\begin{align}
\label{dhr1}
   \left( -\partial_y^2 + k^2 + \frac{b''(y)}{b(y) - \lambda  + i\iota \epsilon } \right) \digamma_{k, \epsilon}^\iota (y,\lambda ) = r(y,\lambda),
\end{align}
where 
\begin{align}
\label{rhs:F}
    r(y,\lambda) := 
    \begin{cases}
        \mathcal{R}_{0,0 ,\epsilon}^\iota(y- y_{j*},\lambda ), & |k \delta(\Lambda)| \ll 1\\
        g_{k, \epsilon}^\iota(y,\lambda ), & |k \delta(\Lambda )| \gtrsim 1
    \end{cases}. 
\end{align}
We reformulate \eqref{dhr1} as 
\begin{align}
    \digamma_{k, \epsilon}^\iota + T_\Theta \digamma_{k, \epsilon}^\iota = \int_\mathbb{T} \mathcal{G}_k^j(y,z; \Lambda) r(z,\lambda) dz .
\end{align}
The bound then follows from Proposition~\ref{DeC7} and Lemmas~\ref{gr:bdds} and~\ref{g:bdds}.

\label{lem:lam1}
Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma_{j, \delta_0} \setminus \{b(y_{j*}) \}$, $\iota\in\{\pm\}, \epsilon \in (0, \epsilon_0) $. Then for any $\theta \in (0, 1/4]$ we have the following bound:
\begin{equation}\label{DCM7}
\norm{  \partial_\lambda \digamma_{k, \epsilon}^\iota  - \mathcal{S}^\iota_{1,0,\epsilon} }_{X^{0,0}} \lesssim \frac{\big\|\omega_{0k}\big\|_{H^4_k}}{|k|^{3/2- \theta}},
\end{equation}
where
\begin{equation}\label{DCM7.0}
\begin{split}
&\mathcal{S}^\iota_{1, 0, \epsilon}(y,\lambda):=\, -\chi_{j, \delta}^*(y)\digamma^\iota_{k,\epsilon}(y,\lambda)\frac{b''(y)}{(b'(y))^2}\log\frac{b(y)-\lambda+i\iota\epsilon}{\delta^2(\Lambda)}.\\
                                                                                                         
\end{split}
\end{equation}

Equations \eqref{BDC2}, \eqref{E:eq}, and \eqref{rhs:F} yield
                                                                                 
\begin{align}
    \left(-\partial_y^2 + k^2 + \frac{b''(y)}{b(y) - \lambda + i \iota \epsilon } \right) \partial_\lambda  \digamma_{k, \epsilon}^\iota(y,\lambda) =  - \frac{b''(y)  \digamma_{k, \epsilon}^\iota  }{(b(y) -\lambda + i \iota \epsilon)^2} + \partial_\lambda r(y,\lambda ). 
\end{align}
Denoting the right-hand side of the equation satisfied by $\partial_\lambda  \digamma_{k, \epsilon}^\iota(y,\lambda) - \mathcal{S}_{1,0, \epsilon}^\iota $ as $\mathcal{R}_{1,0, \epsilon}^\iota$, we solve for $\partial_\lambda \digamma_{k, \epsilon}^\iota   -  \mathcal{S}_{1,0, \epsilon}^\iota$ as follows:
\begin{align}
    \partial_\lambda \digamma_{k, \epsilon}^\iota   -  \mathcal{S}_{1,0, \epsilon}^\iota   + T_\Theta (\partial_\lambda \digamma_{k, \epsilon}^\iota   -  \mathcal{S}_{1,0, \epsilon}^\iota) = \int_\mathbb{T} \mathcal{G}_k^j(y,z; \Lambda) \mathcal{R}_{1,0, \epsilon}^\iota(z,\lambda) dz .
\end{align}
After a direct computation to determine $\mathcal{R}_{1,0, \epsilon}^\iota$,
\eqref{DCM7} follows from  Proposition \ref{DeC7}, the bound \eqref{DCM2}, and Lemmas \ref{dint}, \ref{g:bdds}, \ref{gr:bdds}, and \ref{mGk50}.

\label{lem:gd1}
Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma_{j, \delta_0} \setminus \{b(y_{j*}) \}$, $\iota\in\{\pm\}, \epsilon \in (0, \epsilon_0) $. Then for any $\theta \in (0, 1/4]$ we have the following bound:
\begin{equation}\label{gDCM2}
\begin{split}
\norm{ D_\lambda \digamma_{k, \epsilon}^\iota }_{X^{0,-1}} \lesssim \frac{\big\|\omega_{0k}\big\|_{H^4_k}}{|k|^{3/2- \theta}}.
\end{split}
\end{equation}

Equations \eqref{BDC2}, \eqref{E:eq}, and \eqref{rhs:F} yield
\begin{align}
\label{gd1F}
&\left(
-\partial_y^2+k^2
+\frac{b''(y)}{b(y)-\lambda+i\iota \epsilon}
\right)D_\lambda \digamma_{k, \epsilon}^\iota(y,\lambda)
\nonumber\\
&\quad =
-2b''(y)\partial_y\partial_\lambda \digamma_{k, \epsilon}^\iota(y,\lambda)
-\frac{b'''(y)\digamma_{k, \epsilon}^\iota(y,\lambda)}
       {b(y)-\lambda+i\iota \epsilon} -b'''(y)\partial_\lambda \digamma_{k, \epsilon}^\iota(y,\lambda)  +D_\lambda r(y,\lambda).
\end{align}
Denoting the right-hand side  of \eqref{gd1F} as $\mathcal{R}_{0,1, \epsilon}^\iota$, we solve for $D_\lambda \digamma_{k, \epsilon}^\iota$ as follows:
\begin{align}
  D_\lambda \digamma_{k, \epsilon}^\iota   + T_\Theta (D_\lambda \digamma_{k, \epsilon}^\iota) = \int_\mathbb{T} \mathcal{G}_k^j(y,z; \Lambda) \mathcal{R}_{0,1, \epsilon}^\iota(z,\lambda) dz .
\end{align}
The bound \eqref{gDCM2} follows from  Proposition \ref{DeC7},  and  Lemmas  \ref{lem:lam1}, \ref{dint}, \ref{g:bdds}, \ref{gr:bdds}, and \ref{mGk50}.

\label{DCM100}
Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma_{j, \delta_0} \setminus \{b(y_{j*}) \}$, $\iota\in\{\pm\}, \epsilon \in (0, \epsilon_0)$. Then for any $\theta \in (0, 1/4]$ we have the following bound: 
            
                               
                                                                  
                
\begin{equation}\label{DCM9.4}
\norm{ \delta (\Lambda) (\partial_\lambda^2 \digamma_{k, \epsilon}^\iota   - \mathcal{S}_{2, 0, \epsilon}^\iota )}_{X^{1,0}} \lesssim  \frac{\big\|\omega_{0k}\big\|_{H^4_k}}{|k|^{3/2- \theta}},
\end{equation}
where 
\begin{equation}\label{DCM7.4}
\begin{split}
\mathcal{S}_{2, 0, \epsilon}^\iota(y, \lambda) &:=   \frac{\chi_{j, \delta}^*(y) C_1(y)\digamma_{k,\epsilon}^\iota(y,\lambda)}{b(y) - \lambda + i \iota \epsilon}   \\
&+ \chi_{j, \delta}^*(y) \left( C_2(y) D_\lambda \digamma_{k,\epsilon}^\iota(y,\lambda) + C_3(y)\digamma_{k,\epsilon}^\iota(y,\lambda)   \right) \log (\frac{b(y) -\lambda  + i\iota \epsilon }{\delta^2(\Lambda)}),
    
                                                                                                                                             
                                                                                                                                                                       
                                                                                                                                                                                           
   
\end{split}
\end{equation}
\begin{align}
    C_1(y) = \frac{b''(y)}{(b'(y))^2}, \quad C_2(y) = \frac{ -2 b''(y)}{(b'(y))^3}, \quad  C_3(y) = \frac{3 (b''(y))^2 - 2b'''(y) b'(y)  }{(b'(y))^4}.
\end{align}

Equations \eqref{BDC2}, \eqref{E:eq}, and \eqref{rhs:F} yield
\begin{equation}
\begin{aligned}
&\left(-\partial_y^2+k^2+\frac{b''(y)}{b(y)-\lambda+i\iota\epsilon}\right)
\partial_\lambda^2\digamma_{k,\epsilon}^\iota(y,\lambda)\\
&\quad=-2\frac{b''(y)\digamma_{k,\epsilon}^\iota(y,\lambda)}{(b(y)-\lambda+i\iota\epsilon)^3}
-2\frac{b''(y)\partial_\lambda\digamma_{k,\epsilon}^\iota(y,\lambda)}{(b(y)-\lambda+i\iota\epsilon)^2}
+\partial_\lambda^2r(y,\lambda).
\end{aligned}
\end{equation}
Denoting the right-hand side of the equation satisfied by $\partial_\lambda^2  \digamma_{k, \epsilon}^\iota(y,\lambda) - \mathcal{S}_{2,0, \epsilon}^\iota $ as $\mathcal{R}_{2,0, \epsilon}^\iota$, we solve for $\partial_\lambda^2 \digamma_{k, \epsilon}^\iota   -  \mathcal{S}_{2,0, \epsilon}^\iota$ as follows:
\begin{align}
    \partial_\lambda^2 \digamma_{k, \epsilon}^\iota   -  \mathcal{S}_{2,0, \epsilon}^\iota   + T_\Theta (\partial_\lambda^2 \digamma_{k, \epsilon}^\iota   -  \mathcal{S}_{2,0, \epsilon}^\iota) = \int_\mathbb{T} \mathcal{G}_k^j(y,z; \Lambda) \mathcal{R}_{2,0, \epsilon}^\iota(z,\lambda) dz .
\end{align}
After a direct computation to determine $\mathcal{R}_{2,0, \epsilon}^\iota$,
\eqref{DCM9.4} follows from  Proposition \ref{DeC7},  the bounds \eqref{DCM2}, \eqref{gDCM2}, and Lemmas \ref{dint}, \ref{g:bdds}, \ref{gr:bdds}, and \ref{mGk50}.

\label{lem:gd2}
Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma_{j, \delta_0} \setminus{ \{b(y_{j*}) \} }$, $\iota\in\{\pm\}, \epsilon \in (0, \epsilon_0)$. Then for any $\theta \in (0, 1/4]$ we have the following bound: 
