\label{DCM103}
Assume that $\kappa k\in\mathbb{Z}\backslash\{0\}, \lambda\in \Sigma_{j, \delta_0} \setminus \{  b(y_{j*})   \}$, $\iota\in\{\pm\}, \epsilon \in (0, \epsilon_0)$. Then for any $\theta \in (0, 1/4]$ we have the following bound: 
\begin{equation}\label{DCM9.43}
\norm{ \delta^3 (\Lambda) (\partial_\lambda^3 \digamma_{k, \epsilon}^\iota   - \mathcal{S}_{3,0, \epsilon}^\iota )}_{X^{1, 0}} \lesssim  \frac{\big\|\omega_{0k}\big\|_{H^4_k}}{|k|^{3/2- \theta}},
\end{equation}
            
                               
                                                                  
                
where
\begin{align}
    \mathcal{S}_{3, 0 , \epsilon}^\iota(y,\lambda) &:=  \frac{\chi_{j, \delta}^*(y)C_1(y)\digamma_{k, \epsilon}^\iota(y,\lambda)}{ (b(y) - \lambda + i \iota  \epsilon)^2    } \\
    &+ \frac{\chi_{j, \delta}^*(y)(C_2(y) \partial_y \digamma_{k, \epsilon}^\iota(y,\lambda)    + C_3(y) D_\lambda \digamma_{k, \epsilon}^\iota(y,\lambda) + C_4(y) \digamma_{k, \epsilon}^\iota(y,\lambda) )  }{b(y) - \lambda + i \iota \epsilon} \\
    & + \chi_{j, \delta}^*(y)(  C_5(y) D_\lambda^2 \digamma_{k, \epsilon}^\iota(y,\lambda)  +  C_6(y) D_\lambda \digamma_{k, \epsilon}^\iota(y,\lambda) \\
    &+  C_7(y)\digamma_{k, \epsilon}^\iota(y,\lambda) ) \log \frac{b(y)  -\lambda + i  \iota \epsilon  }{\delta^2(\Lambda)},
\end{align}
\begin{align}
&C_1(y) = \frac{b''(y)}{(b'(y))^2} , \quad C_2(y)  = - \frac{b''(y)}{(b'(y))^3}, \quad C_3(y) = \frac{3 b''(y)}{(b'(y))^3}, \quad C_4(y) =    \frac{2b'''(y)}{(b'(y))^3}
-\frac{3(b''(y))^2}{(b'(y))^4}, \\
 &C_5(y) = -\frac{3b''(y)}{(b'(y))^4}, \quad C_6(y) = -\frac{6b'''(y)}{(b'(y))^4}
+\frac{12(b''(y))^2}{(b'(y))^5}, \notag \\
&C_7(y) = -\frac{k^2b''(y)}{(b'(y))^4}
-\frac{3b^{(4)}(y)}{(b'(y))^4}
+\frac{16b''(y)b'''(y)}{(b'(y))^5}
-\frac{15(b''(y))^3}{(b'(y))^6}. \notag 
\end{align}

Equations \eqref{BDC2}, \eqref{E:eq}, and \eqref{rhs:F} yield
    \begin{align}
      &(-\partial_y^2 + k^2 + \frac{b''(y)}{b(y) - \lambda + i \iota  \epsilon }) \partial_\lambda^3 \digamma_{k, \epsilon}^\iota(y,\lambda)  \\
& = 
-\frac{3b''(y)\partial_\lambda^2  \digamma_{k, \epsilon}^\iota(y,\lambda)}
{(b(y)-\lambda+i \iota \epsilon)^2}
-\frac{6b''(y)\partial_\lambda  \digamma_{k, \epsilon}^\iota(y,\lambda)}
{(b(y)-\lambda+i \iota \epsilon)^3}
-\frac{6b''(y) \digamma_{k, \epsilon}^\iota(y,\lambda)}
{(b(y)-\lambda+i \iota \epsilon)^4}
+\partial_\lambda^3 r(y,\lambda).
\end{align}
Denoting the right-hand side of the equation satisfied by $\partial_\lambda^3  \digamma_{k, \epsilon}^\iota(y,\lambda) - \mathcal{S}_{3,0, \epsilon}^\iota $ as $\mathcal{R}_{3,0, \epsilon}^\iota$, we solve for $\partial_\lambda^3 \digamma_{k, \epsilon}^\iota   -  \mathcal{S}_{3,0, \epsilon}^\iota$ as follows:
\begin{align}
    \partial_\lambda^3 \digamma_{k, \epsilon}^\iota   -  \mathcal{S}_{3,0, \epsilon}^\iota   + T_\Theta (\partial_\lambda^3 \digamma_{k, \epsilon}^\iota   -  \mathcal{S}_{3,0, \epsilon}^\iota) = \int_\mathbb{T} \mathcal{G}_k^j(y,z; \Lambda) \mathcal{R}_{3,0, \epsilon}^\iota(z,\lambda) dz .
\end{align}
After a direct computation to determine $\mathcal{R}_{3,0, \epsilon}^\iota$,
\eqref{DCM9.43} follows from  Proposition \ref{DeC7},  the bounds \eqref{DCM2}, \eqref{gDCM2}, and Lemmas \ref{dint}, \ref{g:bdds}, \ref{gr:bdds}, and \ref{mGk50}.

