\label{boundary}
For $\kappa k \in \mathbb{Z} \setminus \{0 \}$,  $\lambda=b(y_{j*})$, $0<\epsilon<\epsilon_0$, and $\theta\in(0,1/4]$, we have the following bound:
\begin{equation}\label{bdphi}
    \norm{\phi_{k,\epsilon}^{+}-\phi_{k,\epsilon}^{-}}_{X^{\theta,0}}
    \lesssim \delta^2(\Lambda)\big\|\omega_{0k}\big\|_{H_k^4}.
\end{equation}
In particular, 
\begin{equation}\label{bdphi0}
    \lim_{\epsilon\to0+}
    \left[\phi_{k,\epsilon}^{+}(y,b(y_{j*}))
    -\phi_{k,\epsilon}^{-}(y,b(y_{j*}))\right]=0,
