\end{equation}

\label{boundary1}
For $\kappa k \in \mathbb{Z}\setminus \{0 \}$,  $\lambda=b(y_{j*})$, $0<\epsilon<\epsilon_0$, and $\theta\in(0,1/4]$, we have the following bound:
\begin{equation}\label{bdlam}
    \norm{\partial_\lambda\phi_{k,\epsilon}^{+}-\partial_\lambda\phi_{k,\epsilon}^{-}}_{X^{1,0}}
    \lesssim \delta^{1-\theta}(\Lambda)\big\|\omega_{0k}\big\|_{H_k^4}.
\end{equation}
In particular,
\begin{equation}\label{bdlam0}
